def stream_sequence(filename):
    try:
        gzipped, fastq = _is_fastq(filename)

        if not gzipped:
            handle = open(filename, "rb")
        else:
            #handle = os.popen("gunzip -c {0}".format(filename))
            gz = gzip.open(filename, "rb")
            handle = io.BufferedReader(gz)

        if fastq:
            for line, (hdr, seq, _) in enumerate(_read_fastq(handle)):
                if b'@' in hdr:
                    raise FastaError("Fasta/q sequence header has '@' symbol in file: {0}, entry {1}"
                                     .format(filename, line))
                if not _validate_seq(seq):
                    raise FastaError("Invalid sequence symbol in file: {0}, entry {1}"
                                     .format(filename, line))
                yield _STR(hdr), _STR(_to_acgt_bytes(seq))
        else:
            for line, (hdr, seq) in enumerate(_read_fasta(handle)):
                if b'@' in hdr:
                    raise FastaError("Fasta/q sequence header has '@' symbol in file: {0}, entry {1}"
                                     .format(filename, line))
                if not _validate_seq(seq):
                    raise FastaError("Invalid sequence symbol in file: {0}, entry {1}"
                                     .format(filename, line))
                yield _STR(hdr), _STR(_to_acgt_bytes(seq))

    except IOError as e:
        raise FastaError(e)

def merge_single_bp(BP, sample_order, v_id, use_product, vcf, vcf_out, include_genotypes):

    A = BP[0].l.rstrip().split('\t')
    var = Variant(A,vcf)
    try:
        sname = var.get_info('SNAME')
        var.set_info('SNAME', sname + ':' + var.var_id)
    except KeyError:
        pass
    var.var_id=str(v_id)

    if use_product:
        var.set_info('ALG', 'PROD')
    else:
        var.set_info('ALG', 'SUM')

    GTS = None
    if include_genotypes:
        null_string = null_format_string(A[8])
        gt_dict = { sname: A[9] }
        GTS = '\t'.join([gt_dict.get(x, null_string) for x in sample_order])
        var.gts = None
        var.gts_string = GTS

    return var

