def get_first_conv_layer(layers, get_act=False):
    """Return the first convolutional layers in a stack of layer.

    Parameters
    ----------
    layers: list
        List of Keras layers.
    get_act: bool
        Return the activation layer after the convolutional weight layer.

    Returns
    -------
    Keras layer
        Convolutional layer or tuple of convolutional layer and activation layer
        if `get_act=True`.
    """
    conv_layer = None
    act_layer = None
    for layer in layers:
        if isinstance(layer, kl.Conv1D) and layer.input_shape[-1] == 4:
            conv_layer = layer
            if not get_act:
                break
        elif conv_layer and isinstance(layer, kl.Activation):
            act_layer = layer
            break
    if not conv_layer:
        raise ValueError('Convolutional layer not found')
    if get_act:
        if not act_layer:
            raise ValueError('Activation layer not found')
        return (conv_layer, act_layer)
    else:
        return conv_layer

def log_prob(self, value: torch.Tensor) -> torch.Tensor:
    """Log probability."""
    try:
        self._validate_sample(value)
    except ValueError:
        warnings.warn(
            "The value argument must be within the support of the distribution",
            UserWarning,
            stacklevel=settings.warnings_stacklevel,
        )
    return log_mixture_nb(
        value,
        self.mu1,
        self.mu2,
        self.theta1,
        self.theta2,
        self.mixture_logits,
        eps=1e-08,
    )

def Get_prior_allele_mat(self, read_smpl_count, alt_smpl_count, cell_no_threshold, total_depth, Alt_freq, pe):
    if ((read_smpl_count > cell_no_threshold - 1) & (alt_smpl_count == 1)):
        prior_allele_mat = allele_prior(0.2)
    elif ((read_smpl_count > cell_no_threshold) & (alt_smpl_count == 2) & (total_depth > 30) & (Alt_freq < 0.1)):
        prior_allele_mat = allele_prior(0.1)
    else:
        prior_allele_mat = allele_prior(pe)
    return prior_allele_mat

