def find_read_endpoints(alignment_file, template):
    CONS_ALN_RATE = trestle_config.vals["cons_aln_rate"]
    read_endpoints = {}
    aligns = _read_alignment(alignment_file, template, CONS_ALN_RATE)
    if aligns and aligns[0]:
        for aln in aligns[0]:
            read_header = aln.qry_id
            start = aln.trg_start
            end = aln.trg_end
            if read_header not in read_endpoints:
                read_endpoints[read_header] = (start, end)
    else:
        logger.debug("No read alignment to template, no read_endpoints")
    return read_endpoints

def length(self):
    if not self.edge_sequences:
        return 0

    return sum([s.edge_seq_len
                for s in self.edge_sequences]) // len(self.edge_sequences)

def save(self, path: str, only_used_genes: bool = True) -> None:
    r"""
    Save BLAST object to a directory.

    Parameters
    ----------
    path
        Specifies a path to save the BLAST object.
    only_used_genes
        Whether to preserve only the genes used by models.
    """
    if not os.path.exists(path):
        os.makedirs(path)
    if self.ref is not None:
        if only_used_genes:
            if "__libsize__" not in self.ref.obs.columns:
                data.compute_libsize(
                    self.ref
                )  # So that align will still work properly
            ref = data.select_vars(
                self.ref,
                np.unique(np.concatenate([model.genes for model in self.models])),
            )
        ref.uns["distance_metric"] = self.distance_metric.__name__
        ref.uns["n_posterior"] = self.n_posterior
        ref.uns["n_empirical"] = self.n_empirical
        ref.uns["cluster_empirical"] = self.cluster_empirical
        ref.uns["eps"] = self.eps if self.eps is not None else "None"
        if self.latent is not None:
            ref.uns["latent"] = self.latent
        if self.latent is not None:
            ref.uns["cluster"] = self.cluster
        if self.empirical is not None:
            ref.uns["empirical"] = {
                str(i): item for i, item in enumerate(self.empirical)
            }
        ref.uns["posterior"] = {
            str(i): item
            for i, item in enumerate(self.posterior)
            if item is not None
        }
        ref.write(os.path.join(path, "ref.h5ad"))
    for i in range(len(self)):
        self.models[i].save(os.path.join(path, f"model_{i}"))

def assemble(args, run_params, out_file, log_file, config_path):
    logger.info("Assembling disjointigs")
    logger.debug("-----Begin assembly log------")
    cmdline = [ASSEMBLE_BIN, "assemble", "--reads", ",".join(args.reads), "--out-asm", out_file,
               "--config", config_path, "--log", log_file, "--threads", str(1 if args.deterministic else args.threads)]
    if args.debug:
        cmdline.append("--debug")
    if args.meta:
        cmdline.append("--meta")
    #if args.short_mode:
    #    cmdline.append("--short")
    if args.genome_size:
        cmdline.extend(["--genome-size", str(args.genome_size)])
    #if args.kmer_size:
    #    cmdline.extend(["--kmer", str(args.kmer_size)])

    cmdline.extend(["--min-ovlp", str(run_params["min_overlap"])])
    if run_params["min_read_length"] > 0:
        cmdline.extend(["--min-read", str(run_params["min_read_length"])])

    if args.extra_params:
        cmdline.extend(["--extra-params", args.extra_params])

    #if args.min_kmer_count is not None:
    #    cmdline.extend(["-m", str(args.min_kmer_count)])
    #if args.max_kmer_count is not None:
    #    cmdline.extend(["-x", str(args.max_kmer_count)])

    try:
        logger.debug("Running: " + " ".join(cmdline))
        subprocess.check_call(cmdline)
    except subprocess.CalledProcessError as e:
        if e.returncode == -9:
            logger.error("Looks like the system ran out of memory")
        raise AssembleException(str(e))
    except OSError as e:
        raise AssembleException(str(e))

def get_population_AF(self, svcall: SVCall) -> tuple[float, int] | None:
    """
    Returns the population AF and population size for the given SVCall. Returns None if the variant is not found in the population SNF.
    """
    if svcall.contig not in self._blocks:
        self._blocks[svcall.contig] = self.get_all_blocks(svcall.contig)

    block = str(self._calculate_block_index(svcall.pos))
    best_dist = None
    best_variant = None
    try:
        for pv in self._blocks[svcall.contig][block][svcall.svtype]:
            pv: PopulationVariant
            dist = pv.match(svcall)
            if dist is not None:
                if best_dist is None or dist < best_dist:
                    best_dist = dist
                    best_variant = pv
    except KeyError:
        ...
    else:
        if best_variant is not None:
            return round(best_variant.af, 5), best_variant.genotyped_sample_count

    return None

