def conveRt(A, args):
    minNumCols = min([6 + len(y[-1]) for y in A])

    if any([x < 6 and x != 0 for x in [args["C"], args["P"], args["Q"]]]):
        print(
            "Valid column numbers must be given.  Column numbering starts with 1.  Cannot use required PGL column."
        )
        exit(1)
    if any([x > minNumCols for x in [args["C"], args["P"], args["Q"]]]):
        print("A specified column exceeds the number of columns present in the file")
        exit(1)

    res = _formatForConvert(A, args["C"] - 1, args["P"] - 1, args["Q"] - 1)

    if __name__ == "__main__":
        if len(res) != 0:
            try:
                print(
                    "chromA\tstartA\tstopA\tchromB\tstartB\tstopB\tcount\tpValue\tqValue"
                )
                print(("\n".join(res)))
            except IOError as e:
                if e.errno == 32:
                    exit()
    else:
        funcOut = ""
        funcOut += (
            "chromA\tstartA\tstopA\tchromB\tstartB\tstopB\tcount\tpValue\tqValue\n"
        )
        funcOut += "\n".join(res)
        return funcOut

