def __CalculateLambda(self, config, stats):
	logger.info('Started calculating lambda_gen')

	Fgc_Ngc_norm = dict()
	Fgc_Ngc_abnorm	= dict()	
	step = 61
	count = 0

	for chrom in self.chromosomes:
		logger.debug('Processing chromosome ' + chrom + ' for lambda calculation')
		logger.debug('count = '+str(count))
		self.LoadChrom(config, chrom)
		gem_val_normal = []
		gc_rate_normal = []
		gc_gem_normal = []

		gem_val_abnormal = []
		gc_rate_abnormal = []
		gc_gem_abnormal = []

		median = stats['per_chr_stats'][chrom]['median']
		chrom_line = self.chr_line_dict[chrom]
		logger.debug('chrom_line =  '+str(len(chrom_line)))
		logger.debug(self.chr_cnv_dict)
		cnv = self.chr_cnv_dict[chrom]
		cnv_line =[]
		centrom_line = []
		sum_cnv =0 
		gem_line = self.chr_gem_dict[chrom]
		for j in cnv:
			sum_cnv += j[1] - j[0] 
			cnv_line.append(xrange(j[0],j[1]+1))
		for j in self.chr_centrom_dict[chrom]:
			centrom_line.append(xrange(j[0],j[1]+1))
		logger.debug('sum_cnv = '+str(sum_cnv))
		logger.debug('len(gem_line)= '+str(len(gem_line)))	
		logger.debug('sum_cnv/len(gem_line) = '+str(sum_cnv/float(len(gem_line))))
		if sum_cnv/float(len(gem_line))>0.7:
			logger.info('This chromosome we skip, i.e. the average ploidy is not equal to excepted '+chrom)
			continue
		else:
			count += 1

		normal_fragments_normal = sorted(self.chr_normal_fragments_dict[chrom])
		normal_fragments_unique = sorted(self.chr_normal_fragments_dict_unique[chrom])
		logger.debug('Number of normal fragments = '+str(len(normal_fragments_normal)))
		logger.debug('len(normal_fragments_unique) = '+str(len(normal_fragments_unique)))
		len_lenght = len(self.length_probabilities)
		min_boundaries = int(stats['a'])
		max_boundaries = int(stats['b'])
		len_omega = float(max_boundaries - min_boundaries)
		logger.debug('min_boundaries ='+str(min_boundaries))
		logger.debug('max_boundaries ='+str(max_boundaries))
		logger.debug('len(gem) = '+str(len(gem_line)-max_boundaries))
		logger.debug('len(chr) = '+str(len(chrom_line) - max_boundaries))
		for i in xrange(0, len(gem_line) - max_boundaries, step):
			if i not in cnv_line and i not in centrom_line:
				if gem_line[i] == '!':
					gem_val_normal.append(1)
					abnormal_value = (gem_line[i+min_boundaries:i+max_boundaries].count('!'))/float(len_omega)
					if abnormal_value == 0.0:
						gem_val_abnormal.append(-1)
					else:
						gem_val_abnormal.append(abnormal_value)
				else:
					gem_val_normal.append(-1)
					gem_val_abnormal.append(-1)

		logger.debug('Finished with gem')
		gc_rate =[]
		for i in xrange(0, len(gem_line) - max_boundaries, step):
			if i not in cnv_line and i not in centrom_line: 
				gc_rate.append(round((chrom_line[i : i + median].count('g') + chrom_line[i : i + median].count('c')) / float(median),2))

		gc_gem_normal = [gc_rate[i] * gem_val_normal[i] for i in xrange(len(gc_rate) - 1)]

		logger.debug('All windows are counted, now Fgc')
		for i in xrange(len(gc_gem_normal)):
			if gc_gem_normal[i] < 0:
				gc_gem_normal[i] = 'n'

		for i in set(gc_gem_normal):
			if i not in Fgc_Ngc_norm.keys():
				Fgc_Ngc_norm[i] = {'Fgc':0,'Ngc':0}
			Fgc_Ngc_norm[i]['Ngc'] += gc_gem_normal.count(i)

		for i in xrange(len(gc_rate)):
			if gem_val_abnormal[i]>0:
				if gc_rate[i] not in Fgc_Ngc_abnorm.keys():
					Fgc_Ngc_abnorm[gc_rate[i]] = {'Fgc':0,'Ngc':0}
				Fgc_Ngc_abnorm[gc_rate[i]]['Ngc'] += 1/gem_val_abnormal[i]

		norm_ind = 0
		ind_left = 0
		logger.debug('lenght gc_gem = ' + str(len(gc_gem_normal)))
		logger.debug('lenght gem len = ' + str(len(gem_val_normal)))
		logger.debug('lenght gc_gem_normal = '+str(len(gc_gem_normal)))
		for i in normal_fragments_normal:
			if i > len(gem_line) - median:
				break
			ind_left += 1	
			if ind_left % 50000 == 0:
				logger.debug('Already processed ' + str(ind_left) + ' fragments, left ' + str(len(normal_fragments_normal) - ind_left))
			if i % step == 0:
				if (i / step)>len(gc_gem_normal)-1:
					continue
				else:
					if gc_gem_normal[i / step] != 'n':
						Fgc_Ngc_norm[gc_gem_normal[i / step]]['Fgc'] += 1
			ind_left = 0
		for i in normal_fragments_unique:
			if i > len(chrom_line) - max_boundaries:
				break
			ind_left += 1	
			if i % step == 0:
				if (i / step)>len(gc_gem_normal)-1:
					continue
				else:
					if gem_val_abnormal[i/step]!=-1:
						Fgc_Ngc_abnorm[gc_rate[i/step]]['Fgc'] += 1
		if count == 2:
			break
	lambda_norm = []
	lambda_abnorm = []
	del Fgc_Ngc_norm['n']

	Fgc_Ngc_arr = [Fgc_Ngc_norm,Fgc_Ngc_abnorm]
	for dictionary in Fgc_Ngc_arr:
		if 0.7 not in dictionary.keys():
			dictionary[0.7] = {'Fgc':0,'Ngc':0}
		if 0.3 not in dictionary.keys():
			dictionary[0.3] = {'Fgc':0,'Ngc':0}
		for key in dictionary.keys():
			if key>0.7:
				dictionary[0.7]['Fgc']+=dictionary[key]['Fgc']
				dictionary[0.7]['Ngc']+=dictionary[key]['Ngc']
				del dictionary[key]
			if key<0.3:
				dictionary[0.3]['Fgc']+=dictionary[key]['Fgc']
				dictionary[0.3]['Ngc']+=dictionary[key]['Ngc']
				del dictionary[key]

	for i in Fgc_Ngc_norm.keys():
		if Fgc_Ngc_norm[i]['Ngc']!=0:
			logger.debug(str([i, float(Fgc_Ngc_norm[i]['Fgc']) / Fgc_Ngc_norm[i]['Ngc']]))
			lambda_norm.append([i, float(Fgc_Ngc_norm[i]['Fgc']) / Fgc_Ngc_norm[i]['Ngc']])
		else:
			logger.debug(str(i)+str(float(0.0)))
			lambda_norm.append([i, float(0.0)])
	logger.debug('Abnormal lambda')
	for i in Fgc_Ngc_abnorm.keys():
		if Fgc_Ngc_abnorm[i]['Ngc']!=0:
			logger.debug(str([i, float(Fgc_Ngc_abnorm[i]['Fgc']) / Fgc_Ngc_abnorm[i]['Ngc']]))
			lambda_abnorm.append([i, float(Fgc_Ngc_abnorm[i]['Fgc']) / Fgc_Ngc_abnorm[i]['Ngc']])
		else:
			logger.debug(str(i)+str(float(0.0)))
			lambda_abnorm.append([i, float(0.0)])


	lambda_norm = filter(partial(is_not, None), lambda_norm)
	lambda_norm.sort(key = lambda l : l[0])
	lambda_abnorm = filter(partial(is_not, None), lambda_abnorm)
	lambda_abnorm.sort(key = lambda l : l[0])


	logger.debug('lambda normal, len = '+str(len(lambda_norm)))
	for i in Fgc_Ngc_norm.keys():
		logger.debug(str(i) + ' Fgc = ' + str(Fgc_Ngc_norm[i]['Fgc']) + ' Ngc = ' + str(Fgc_Ngc_norm[i]['Ngc']))
	logger.debug('lambda abnormal, len = '+str(len(lambda_abnorm)))
	for i in Fgc_Ngc_abnorm.keys():
		logger.debug(str(i)+ ' Fgc = '+str(Fgc_Ngc_abnorm[i]['Fgc'])+ ' Ngc = '+str(Fgc_Ngc_abnorm[i]['Ngc']))

	#UnloadChrom(config, chrom)
	f = open(config['working_dir'] + config['lambda_file'], 'w')
	f.write('Normal lambda '+'\n')
	for i in lambda_norm:
		f.write(str(i[0])+' '+str(i[1]))
		f.write('\n')
	f.write('Abnormal lambda '+'\n')
	for i in lambda_abnorm:
		f.write(str(i[0])+' '+str(i[1]))
		f.write('\n')
	f.close()
	logger.info('Finished calculating lambda')

	return (lambda_norm,lambda_abnorm)

def finalize_candidates(self, candidates: list['SVCall'], keep_qc_fails, config):
    passed = []
    for svcall in candidates:
        svcall.qc = svcall.qc and postprocessing.qc_sv(svcall, config)
        if not keep_qc_fails and not svcall.qc:
            continue
        svcall.qc = svcall.qc and postprocessing.qc_sv_support(svcall, self.coverage_average_total, config)
        if not keep_qc_fails and not svcall.qc:
            continue

        postprocessing.annotate_sv(svcall, config)

        svcall.qc = svcall.qc and postprocessing.qc_sv_post_annotate(svcall, config)

        if config.dev_trace_read:
            cluster_has_read = False
            for ld in svcall.postprocess.cluster.leads:
                if ld.read_qname == config.dev_trace_read:
                    cluster_has_read = True
            if cluster_has_read:
                import copy
                svcall_copy = copy.deepcopy(svcall)
                svcall_copy.postprocess = None
                print(f"[DEV_TRACE_READ] [4/4] [Task.finalize_candidates] Read {config.dev_trace_read} -> Cluster {svcall.postprocess.cluster.id} -> finalized SVCall, QC={svcall_copy.qc}: {svcall_copy}")

        if not keep_qc_fails and not svcall.qc:
            continue

        svcall.finalize()  # Remove internal information (not written to output) before sending to mainthread for VCF writing
        passed.append(svcall)
    return passed

def genotype_sv(svcall: SVCall, config, phase: tuple | None = None):
    from sniffles.genotyping import GENOTYPER_BY_TYPE, Genotyper

    GENOTYPER_BY_TYPE.get(svcall.svtype, Genotyper)(svcall, config, phase).calculate()

def __CalculateLambda(self, config, stats):
	logger.info('Started calculating lambda_gen')

	Fgc_Ngc_norm = dict()
	Fgc_Ngc_abnorm	= dict()	
	step = 61
	count = 0

	for chrom in self.chromosomes:
		logger.debug('Processing chromosome ' + chrom + ' for lambda calculation')
		logger.debug('count = '+str(count))
		self.LoadChrom(config, chrom)
		gem_val_normal = []
		gc_rate_normal = []
		gc_gem_normal = []

		gem_val_abnormal = []
		gc_rate_abnormal = []
		gc_gem_abnormal = []

		median = stats['per_chr_stats'][chrom]['median']
		chrom_line = self.chr_line_dict[chrom]
		logger.debug('chrom_line =  '+str(len(chrom_line)))
		logger.debug(self.chr_cnv_dict)
		cnv = self.chr_cnv_dict[chrom]
		cnv_line =[]
		centrom_line = []
		sum_cnv =0 
		gem_line = self.chr_gem_dict[chrom]
		for j in cnv:
			sum_cnv += j[1] - j[0] 
			cnv_line.append(xrange(j[0],j[1]+1))
		for j in self.chr_centrom_dict[chrom]:
			centrom_line.append(xrange(j[0],j[1]+1))
		logger.debug('sum_cnv = '+str(sum_cnv))
		logger.debug('len(gem_line)= '+str(len(gem_line)))	
		logger.debug('sum_cnv/len(gem_line) = '+str(sum_cnv/float(len(gem_line))))
		if sum_cnv/float(len(gem_line))>0.7:
			logger.info('This chromosome we skip, i.e. the average ploidy is not equal to excepted '+chrom)
			continue
		else:
			count += 1

		normal_fragments_normal = sorted(self.chr_normal_fragments_dict[chrom])
		normal_fragments_unique = sorted(self.chr_normal_fragments_dict_unique[chrom])
		logger.debug('Number of normal fragments = '+str(len(normal_fragments_normal)))
		logger.debug('len(normal_fragments_unique) = '+str(len(normal_fragments_unique)))
		len_lenght = len(self.length_probabilities)
		min_boundaries = int(stats['a'])
		max_boundaries = int(stats['b'])
		len_omega = float(max_boundaries - min_boundaries)
		logger.debug('min_boundaries ='+str(min_boundaries))
		logger.debug('max_boundaries ='+str(max_boundaries))
		logger.debug('len(gem) = '+str(len(gem_line)-max_boundaries))
		logger.debug('len(chr) = '+str(len(chrom_line) - max_boundaries))
		for i in xrange(0, len(gem_line) - max_boundaries, step):
			if i not in cnv_line and i not in centrom_line:
				if gem_line[i] == '!':
					gem_val_normal.append(1)
					abnormal_value = (gem_line[i+min_boundaries:i+max_boundaries].count('!'))/float(len_omega)
					if abnormal_value == 0.0:
						gem_val_abnormal.append(-1)
					else:
						gem_val_abnormal.append(abnormal_value)
				else:
					gem_val_normal.append(-1)
					gem_val_abnormal.append(-1)

		logger.debug('Finished with gem')
		gc_rate =[]
		for i in xrange(0, len(gem_line) - max_boundaries, step):
			if i not in cnv_line and i not in centrom_line: 
				gc_rate.append(round((chrom_line[i : i + median].count('g') + chrom_line[i : i + median].count('c')) / float(median),2))

		gc_gem_normal = [gc_rate[i] * gem_val_normal[i] for i in xrange(len(gc_rate) - 1)]

		logger.debug('All windows are counted, now Fgc')
		for i in xrange(len(gc_gem_normal)):
			if gc_gem_normal[i] < 0:
				gc_gem_normal[i] = 'n'

		for i in set(gc_gem_normal):
			if i not in Fgc_Ngc_norm.keys():
				Fgc_Ngc_norm[i] = {'Fgc':0,'Ngc':0}
			Fgc_Ngc_norm[i]['Ngc'] += gc_gem_normal.count(i)

		for i in xrange(len(gc_rate)):
			if gem_val_abnormal[i]>0:
				if gc_rate[i] not in Fgc_Ngc_abnorm.keys():
					Fgc_Ngc_abnorm[gc_rate[i]] = {'Fgc':0,'Ngc':0}
				Fgc_Ngc_abnorm[gc_rate[i]]['Ngc'] += 1/gem_val_abnormal[i]

		norm_ind = 0
		ind_left = 0
		logger.debug('lenght gc_gem = ' + str(len(gc_gem_normal)))
		logger.debug('lenght gem len = ' + str(len(gem_val_normal)))
		logger.debug('lenght gc_gem_normal = '+str(len(gc_gem_normal)))
		for i in normal_fragments_normal:
			if i > len(gem_line) - median:
				break
			ind_left += 1	
			if ind_left % 50000 == 0:
				logger.debug('Already processed ' + str(ind_left) + ' fragments, left ' + str(len(normal_fragments_normal) - ind_left))
			if i % step == 0:
				if (i / step)>len(gc_gem_normal)-1:
					continue
				else:
					if gc_gem_normal[i / step] != 'n':
						Fgc_Ngc_norm[gc_gem_normal[i / step]]['Fgc'] += 1
			ind_left = 0
		for i in normal_fragments_unique:
			if i > len(chrom_line) - max_boundaries:
				break
			ind_left += 1	
			if i % step == 0:
				if (i / step)>len(gc_gem_normal)-1:
					continue
				else:
					if gem_val_abnormal[i/step]!=-1:
						Fgc_Ngc_abnorm[gc_rate[i/step]]['Fgc'] += 1
		if count == 2:
			break
	lambda_norm = []
	lambda_abnorm = []
	del Fgc_Ngc_norm['n']

	Fgc_Ngc_arr = [Fgc_Ngc_norm,Fgc_Ngc_abnorm]
	for dictionary in Fgc_Ngc_arr:
		if 0.7 not in dictionary.keys():
			dictionary[0.7] = {'Fgc':0,'Ngc':0}
		if 0.3 not in dictionary.keys():
			dictionary[0.3] = {'Fgc':0,'Ngc':0}
		for key in dictionary.keys():
			if key>0.7:
				dictionary[0.7]['Fgc']+=dictionary[key]['Fgc']
				dictionary[0.7]['Ngc']+=dictionary[key]['Ngc']
				del dictionary[key]
			if key<0.3:
				dictionary[0.3]['Fgc']+=dictionary[key]['Fgc']
				dictionary[0.3]['Ngc']+=dictionary[key]['Ngc']
				del dictionary[key]

	for i in Fgc_Ngc_norm.keys():
		if Fgc_Ngc_norm[i]['Ngc']!=0:
			logger.debug(str([i, float(Fgc_Ngc_norm[i]['Fgc']) / Fgc_Ngc_norm[i]['Ngc']]))
			lambda_norm.append([i, float(Fgc_Ngc_norm[i]['Fgc']) / Fgc_Ngc_norm[i]['Ngc']])
		else:
			logger.debug(str(i)+str(float(0.0)))
			lambda_norm.append([i, float(0.0)])
	logger.debug('Abnormal lambda')
	for i in Fgc_Ngc_abnorm.keys():
		if Fgc_Ngc_abnorm[i]['Ngc']!=0:
			logger.debug(str([i, float(Fgc_Ngc_abnorm[i]['Fgc']) / Fgc_Ngc_abnorm[i]['Ngc']]))
			lambda_abnorm.append([i, float(Fgc_Ngc_abnorm[i]['Fgc']) / Fgc_Ngc_abnorm[i]['Ngc']])
		else:
			logger.debug(str(i)+str(float(0.0)))
			lambda_abnorm.append([i, float(0.0)])


	lambda_norm = filter(partial(is_not, None), lambda_norm)
	lambda_norm.sort(key = lambda l : l[0])
	lambda_abnorm = filter(partial(is_not, None), lambda_abnorm)
	lambda_abnorm.sort(key = lambda l : l[0])


	logger.debug('lambda normal, len = '+str(len(lambda_norm)))
	for i in Fgc_Ngc_norm.keys():
		logger.debug(str(i) + ' Fgc = ' + str(Fgc_Ngc_norm[i]['Fgc']) + ' Ngc = ' + str(Fgc_Ngc_norm[i]['Ngc']))
	logger.debug('lambda abnormal, len = '+str(len(lambda_abnorm)))
	for i in Fgc_Ngc_abnorm.keys():
		logger.debug(str(i)+ ' Fgc = '+str(Fgc_Ngc_abnorm[i]['Fgc'])+ ' Ngc = '+str(Fgc_Ngc_abnorm[i]['Ngc']))

	#UnloadChrom(config, chrom)
	f = open(config['working_dir'] + config['lambda_file'], 'w')
	f.write('Normal lambda '+'\n')
	for i in lambda_norm:
		f.write(str(i[0])+' '+str(i[1]))
		f.write('\n')
	f.write('Abnormal lambda '+'\n')
	for i in lambda_abnorm:
		f.write(str(i[0])+' '+str(i[1]))
		f.write('\n')
	f.close()
	logger.info('Finished calculating lambda')

	return (lambda_norm,lambda_abnorm)

def annotate(g, fname, tables, feature_strand=False, in_memory=False,
        header=None, out=sys.stdout, _chrom=None, parallel=False):
    """
    annotate bed file in fname with tables.
    distances are integers for distance. and intron/exon/utr5 etc for gene-pred
    tables. if the annotation features have a strand, the distance reported is
    negative if the annotation feature is upstream of the feature in question
    if feature_strand is True, then the distance is negative if t
    """
    close = False
    if isinstance(out, basestring):
        out = nopen(out, "w")
        close = True


    if parallel:
        import multiprocessing
        import signal
        p = multiprocessing.Pool(initializer=lambda:
                                signal.signal(signal.SIGINT, signal.SIG_IGN))
        chroms = _split_chroms(fname)

        def write_result(fanno, written=[False]):
            for i, d in enumerate(reader(fanno, header="ordered")):
                if i == 0 and written[0] == False:
                    print("\t".join(d.keys()), file=out)
                    written[0] = True
                print("\t".join(x if x else "NA" for x in d.values()), file=out)
            os.unlink(fanno)
            os.unlink(fanno.replace(".anno", ""))

        for fchrom, (fout, fanno) in chroms:
            p.apply_async(annotate, args=(g.db, fout.name, tables, feature_strand, False, # True causes it to silently fail, resulting in nothing being writting in the output file
                                 header, fanno, fchrom),
                                 callback=write_result)
        p.close()
        p.join()
        return out.name

    if isinstance(g, basestring):
        from . import Genome
        g = Genome(g)
    if in_memory:
        from . intersecter import Intersecter
        intersecters = [] # 1 per table.
        for t in tables:
            q = getattr(g, t) if isinstance(t, basestring) else t
            if _chrom is not None:
                q = q.filter_by(chrom=_chrom)
            table_iter = q #page_query(q, g.session)
            intersecters.append(Intersecter(table_iter))

    elif isinstance(fname, basestring) and os.path.exists(fname) \
            and sum(1 for _ in nopen(fname)) > 25000:
        print("annotating many intervals, may be faster using in_memory=True", file=sys.stderr)
    if header is None:
        header = []
    extra_header = []
    for j, toks in enumerate(reader(fname, header=False)):
        if j == 0 and not header:
            if not (toks[1] + toks[2]).isdigit():
                header = toks
        if j == 0:
            for t in tables:
                annos = (getattr(g, t) if isinstance(t, basestring) else t).first().anno_cols
                h = t if isinstance(t, basestring) else t._table.name if hasattr(t, "_table") else t.first()._table.name
                extra_header += ["%s_%s" % (h, a) for a in annos]

            if 0 != len(header):
                if not header[0].startswith("#"):
                    header[0] = "#" + header[0]
                print("\t".join(header + extra_header), file=out)
            if header == toks: continue

        if not isinstance(toks, ABase):
            f = Feature()
            f.chrom = toks[0]
            f.txStart = int(toks[1])
            f.txEnd = int(toks[2])
            try:
                f.strand = toks[header.index('strand')]
            except ValueError:
                pass
        else:
            f = toks
            # for now, use the objects str to get the columns
            # might want to use getattr on the original cols

            toks = f.bed(*header).split("\t")
        sep = "^*^"
        for ti, tbl in enumerate(tables):
            if in_memory:
                objs = intersecters[ti].knearest(int(toks[1]), int(toks[2]), chrom=toks[0], k = 1)
            else:
                objs = g.knearest(tbl, toks[0], int(toks[1]), int(toks[2]), k=1)
            if len(objs) == 0:
                print("\t".join(toks + ["", "", ""]), file=out)
                continue

            gp = hasattr(objs[0], "exonStarts")
            names = [o.gene_name for o in objs]
            if feature_strand:
                strands = [-1 if f.is_upstream_of(o) else 1 for o in objs]
            else:
                strands = [-1 if o.is_upstream_of(f) else 1 for o in objs]

            # dists can be a list of tuples where the 2nd item is something
            # like 'island' or 'shore'
            dists = [o.distance(f, features=gp) for o in objs]
            pure_dists = [d[0] if isinstance(d, (tuple, list)) else d for d in dists]

            # convert to negative if the feature is upstream of the query
            for i, s in enumerate(strands):
                if s == 1: continue
                if isinstance(pure_dists[i], basestring): continue
                pure_dists[i] *= -1

            for i, (pd, d) in enumerate(zip(pure_dists, dists)):
                if isinstance(d, tuple):
                    if len(d) > 1:
                        dists[i] = "%s%s%s" % (pd, sep, sep.join(d[1:]))
                    else:
                        dists[i] = pd
            # keep uniqe name, dist combinations (occurs because of
            # transcripts)
            name_dists = set(["%s%s%s" % (n, sep, d) \
                            for (n, d) in zip(names, dists)])
            name_dists = [nd.split(sep) for nd in name_dists]

            # just take the first gene name if they are all the same
            if len(set(nd[0] for nd in name_dists)) == 1:
                toks.append(name_dists[0][0])
            else:
                toks.append(";".join(nd[0] for nd in name_dists))

            # iterate over the feat type, dist cols
            for i in range(1, len(name_dists[0])):

                toks.append(";".join(nd[i] for nd in name_dists))
        print("\t".join(toks), file=out)

    if close:
        out.close()
    return out.name

def get_sparse_from_igraph(graph, weight_attr=None):
    from scipy.sparse import csr_matrix
    edges = graph.get_edgelist()
    if weight_attr is None:
        weights = [1] * len(edges)
    else:
        weights = graph.es[weight_attr]
    if not graph.is_directed():
        edges.extend([(v, u) for u, v in edges])
        weights.extend(weights)
    shape = graph.vcount()
    shape = (shape, shape)
    if len(edges) > 0:
        return csr_matrix((weights, zip(*edges)), shape=shape)
    else:
        return csr_matrix(shape)

def mean_balanced_accuracy(
    true: np.ndarray,
    pred: np.ndarray,
    expectation: pd.DataFrame,
    population_weighed: bool = False,
) -> float:
    df = class_specific_accuracy(true, pred, expectation)
    if population_weighed:
        return (df["accuracy"] * df["number"]).sum() / df["number"].sum()
    return df["accuracy"].mean()

