def get_queries_on_target_association(self):
    """
    For each target, get the list of queries associated to it

    :return: list of queries associated to each target
    :rtype: dict
    """
    gravity_contig = self.compute_gravity_contigs()[0]
    queries_on_target = {}
    for contig, chr_blocks in gravity_contig.items():
        # Find best block:
        max_number = 0
        max_chr = None
        for chrm, size in chr_blocks.items():
            if size > max_number:
                max_number = size
                max_chr = chrm
        if max_chr is not None:
            if max_chr not in queries_on_target:
                queries_on_target[max_chr] = []
            queries_on_target[max_chr].append(contig)
    return queries_on_target

def vel_p(
    self, S: Union[csr_matrix, np.ndarray], P: Union[csr_matrix, np.ndarray]
) -> Union[csr_matrix, np.ndarray]:
    """Calculate the protein velocity.

    Args:
        S: A matrix of spliced mRNA counts. Dimension: genes x cells.
        P: A matrix of protein counts. Dimension: genes x cells.

    Returns:
        Each column of V is a velocity vector for the corresponding cell. Dimension: genes x cells.
    """

    t = self.parameters["t"]
    t_uniq, t_uniq_cnt = np.unique(self.parameters["t"], return_counts=True)
    if self.parameters["eta"] is not None and self.parameters["delta"] is not None:
        if self.parameters["eta"].ndim == 1:
            eta = np.repeat(self.parameters["eta"].reshape((-1, 1)), S.shape[1], axis=1)
        elif self.parameters["eta"].shape[1] == S.shape[1]:
            eta = self.parameters["eta"]
        elif self.parameters["eta"].shape[1] == len(t_uniq) and len(t_uniq) > 1:
            eta = np.zeros_like(S.shape)
            for i in range(len(t_uniq)):
                cell_inds = t == t_uniq[i]
                eta[:, cell_inds] = np.repeat(self.parameters["eta"][:, i], t_uniq_cnt[i], axis=1)
        else:
            eta = np.repeat(self.parameters["eta"], S.shape[1], axis=1)

        if len(self.parameters["delta"].shape) == 1:
            delta = np.repeat(
                self.parameters["delta"].reshape((-1, 1)),
                S.shape[1],
                axis=1,
            )
        elif self.parameters["delta"].shape[1] == S.shape[1]:
            delta = self.parameters["delta"]
        elif self.parameters["delta"].shape[1] == len(t_uniq) and len(t_uniq) > 1:
            delta = np.zeros_like(S.shape)
            for i in range(len(t_uniq)):
                cell_inds = t == t_uniq[i]
                delta[:, cell_inds] = np.repeat(self.parameters["delta"][:, i], t_uniq_cnt[i], axis=1)
        else:
            delta = np.repeat(self.parameters["delta"], S.shape[1], axis=1)

        V = (
            csr_matrix(eta, dtype=np.float64).multiply(S) - csr_matrix(delta, dtype=np.float64).multiply(P)
            if issparse(P)
            else eta * S - delta * P
        )
    else:
        V = np.nan
    return V

def _correct_mut_counts(self, populations, tree_idx):
  for sidx, subclone in populations.items():
    # Note that only mutass entries for subclones with (> 0 SSMs or > 0
    # CNVs) will exist. Thus, no mutass entry will exist for node 0, as it
    # never has SSMs or CNVs.
    if sidx == 0:
      continue
    for mut_type in ('ssms', 'cnvs'):
      subclone['num_%s' % mut_type] = len(self._mutass[tree_idx][sidx][mut_type])

def predict_pseudotime(self, data: numpy.ndarray):
    res = keras.backend.function(inputs=[self.model.get_layer('input').input],
                                 outputs=[self.model.get_layer('embedding').output]
                                 )([data])
    return numpy.arctan2(res[0][:, 0], res[0][:, 1])

def qc_coverage_samples(self) -> tuple[bool, float | None]:
    var = self.forward_difference_sampler.variance
    if var is None:
        return True, None
    return var < 0.3, float(var)

def __iter__(self):
    for idx, (_hits, _dist, _pval) in enumerate(
        zip(self.hits, self.dist, self.pval)
    ):
        yield Hits(self.blast, [_hits], [_dist], [_pval], self.query[idx, :])

def filter(
    self,
    by: str = "pval",
    cutoff: float = 0.05,
    model_tolerance: int = 0,
    n_jobs: int = 1,
) -> "Hits":
    r"""
    Filter hits by posterior distance or p-value

    Parameters
    ----------
    by
        Specifies a metric based on which to filter hits.
        Should be among {"dist", "pval"}.
    cutoff
        Cutoff when filtering hits.
    model_tolerance
        Maximal number of models allowed in which the cutoff is not
        satisfied, above which the query cell will be rejected.
        Irrelevant for reconciled hits.
    n_jobs
        Number of parallel jobs to run.

    Returns
    -------
    filtered_hits
        Hit object containing remaining hits after filtering
    """
    if by == "pval":
        assert self.pval is not None
        by = Hits.FILTER_BY_PVAL
    else:  # by == "dist"
        by = Hits.FILTER_BY_DIST
    if self.dist[0].ndim == 1:
        hits, dist, pval = [
            _
            for _ in zip(
                *joblib.Parallel(n_jobs=n_jobs, backend="threading")(
                    joblib.delayed(self._filter_reconciled_hits)(
                        _hits, _dist, _pval, by, cutoff
                    )
                    for _hits, _dist, _pval in zip(self.hits, self.dist, self.pval)
                )
            )
        ]
    else:
        hits, dist, pval = [
            _
            for _ in zip(
                *joblib.Parallel(n_jobs=n_jobs, backend="threading")(
                    joblib.delayed(self._filter_hits)(
                        _hits, _dist, _pval, by, cutoff, model_tolerance
                    )
                    for _hits, _dist, _pval in zip(self.hits, self.dist, self.pval)
                )
            )
        ]
    return Hits(self.blast, hits, dist, pval, self.query)

def statRead(self, read):
    global WARNED_BZIP2_ERROR
    seq = read[1]
    qual = read[3]
    seqlen = len(seq)
    gc = 0
    for i in xrange(seqlen):
        self.totalNum[i] += 1
        try:
            qnum = util.qualNum(qual[i])
        except Exception:
            if self.filename.endswith("bz2") and WARNED_BZIP2_ERROR == False:
                WARNED_BZIP2_ERROR = True
                print("WARNING: Incompatible bzip2 format, please note that the file compressed with pbzip2 may have problem. Please compress it with bzip2 insteadly.\n")
            continue
        self.totalQual[i] += qnum
        b = seq[i]
        if b=='G' or b=='C':
            gc += 1
        if b in ALL_BASES:
            self.baseCounts[b][i] += 1
            self.baseTotalQual[b][i] += qnum

        # calculate discontinuity
        left = i-2
        right = i+3
        if left<0:
            left = 0
            right = 5
        elif right >= seqlen:
            right = seqlen
            left = seqlen - 5
        discontinuity = 0
        for j in xrange(left, right-1):
            if seq[j] != seq[j+1]:
                discontinuity += 1
        self.totalDiscontinuity[i] += discontinuity

    #gcPer = int(1000.0* float(gc)/seqlen)
    self.gcHistogram[gc] += 1
    for i in xrange(seqlen - self.kmerLen):
        self.totalKmer += 1
        kmer = seq[i:i+self.kmerLen]
        if kmer in self.kmerCount:
            self.kmerCount[kmer] += 1
        else:
            self.kmerCount[kmer] = 1
            rcKmer = util.reverseComplement(kmer)
            if rcKmer not in self.kmerCount:
                self.kmerCount[rcKmer] = 0

