def _to_model_card(self) -> ModelCard:
    # define tags
    tags = [
        "biology",
        "genomics",
        "single-cell",
        _SCVI_HUB.MODEL_CLS_NAME_TAG.format(self.model_cls_name),
        _SCVI_HUB.SCVI_VERSION_TAG.format(self.scvi_version),
        _SCVI_HUB.ANNDATA_VERSION_TAG.format(self.anndata_version),
    ]
    for m in self.data_modalities:
        tags.append(_SCVI_HUB.MODALITY_TAG.format(m))
    for t in self.tissues:
        tags.append(_SCVI_HUB.TISSUE_TAG.format(t))
    if self.data_is_annotated is not None:
        tags.append(_SCVI_HUB.ANNOTATED_TAG.format(self.data_is_annotated))

    # define the card data, which is the header
    card_data = ModelCardData(
        license=self.license_info,
        library_name=_SCVI_HUB.HF_LIBRARY_NAME,
        tags=tags,
    )

    # flatten the model_init_params into a single dict
    # for example {'kwargs': {'model_kwargs': {'foo': 'bar'}}, 'non_kwargs': {'n_hidden': 128,
    # 'n_latent': 10}}
    # becomes {'n_hidden': 128, 'n_latent': 10, 'foo': 'bar'}
    if "non_kwargs" in self.model_init_params.keys():
        non_kwargs = self.model_init_params["non_kwargs"]
        kwargs = self.model_init_params["kwargs"]
    else:
        non_kwargs = {
            k: v for k, v in self.model_init_params.items() if not isinstance(v, dict)
        }
        kwargs = {k: v for k, v in self.model_init_params.items() if isinstance(v, dict)}
    kwargs = {k: v for (i, j) in kwargs.items() for (k, v) in j.items()}
    # kwargs and non_kwargs keys should be disjoint but if not, we'll just use the original
    # model_init_params
    if len(set(kwargs.keys()).intersection(set(non_kwargs.keys()))) == 0:
        flattened_model_init_params = {**non_kwargs, **kwargs}
    else:
        flattened_model_init_params = self.model_init_params

    # create the content from the template
    content = template.format(
        card_data=card_data.to_yaml(),
        description=self.description,
        model_init_params=json.dumps(flattened_model_init_params, indent=4),
        model_setup_anndata_args=json.dumps(self.model_setup_anndata_args, indent=4),
        model_summary_stats=AnnDataManager._view_summary_stats(
            self.model_summary_stats, as_markdown=True
        ),
        model_data_registry=AnnDataManager._view_data_registry(
            self.model_data_registry, as_markdown=True
        ),
        model_parent_module=self.model_parent_module,
        data_is_minified=_SCVI_HUB.DEFAULT_MISSING_FIELD
        if self.data_is_minified is None
        else self.data_is_minified,
        training_data_url=self.training_data_url or _SCVI_HUB.DEFAULT_NA_FIELD,
        training_code_url=self.training_code_url or _SCVI_HUB.DEFAULT_NA_FIELD,
        references=self.references,
    )

    # finally create and return the actual card
    return ModelCard(content)

def get_sparse_from_igraph(graph, weight_attr=None):
    from scipy.sparse import csr_matrix
    edges = graph.get_edgelist()
    if weight_attr is None:
        weights = [1] * len(edges)
    else:
        weights = graph.es[weight_attr]
    if not graph.is_directed():
        edges.extend([(v, u) for u, v in edges])
        weights.extend(weights)
    shape = graph.vcount()
    shape = (shape, shape)
    if len(edges) > 0:
        return csr_matrix((weights, zip(*edges)), shape=shape)
    else:
        return csr_matrix(shape)

def get_simple_repeats(repeat_graph, alignments_file, edge_seqs):
    next_path_id = 1
    path_ids = {}
    repeats_dict = {}
    MULT = 2

    paths_to_resolve = []
    interesting_edges = set()
    for path in repeat_graph.get_unbranching_paths():
        if not path[0].repetitive or path[0].self_complement:
            continue

        is_simple = True
        inputs = set()
        for in_edge in path[0].node_left.in_edges:
            inputs.add(in_edge.edge_id)
            if in_edge.repetitive:
                is_simple = False

        outputs = set()
        for out_edge in path[-1].node_right.out_edges:
            outputs.add(out_edge.edge_id)
            if out_edge.repetitive:
                is_simple = False

        if not is_simple or len(inputs) != MULT or len(outputs) != MULT:
            continue

        paths_to_resolve.append((path, inputs, outputs))
        interesting_edges.update(set([e.edge_id for e in path]))

    interesting_alignments = []
    for read_aln in iter_alignments(alignments_file):
        repeat_read = False
        for edge_aln in read_aln:
            if edge_aln.edge_id in interesting_edges:
                repeat_read = True
        if repeat_read:
            interesting_alignments.append(read_aln)

    for path, inputs, outputs in paths_to_resolve:
        if path[0].edge_id not in path_ids:
            path_ids[path[0].edge_id] = next_path_id
            path_ids[-path[-1].edge_id] = -next_path_id
            next_path_id += 1
        path_id = path_ids[path[0].edge_id]

        repeat_edge_ids = set([e.edge_id for e in path])
        inner_reads = []
        input_reads = defaultdict(list)
        output_reads = defaultdict(list)
        for read_aln in interesting_alignments:
            repeat_read = False
            for edge_aln in read_aln:
                if edge_aln.edge_id in repeat_edge_ids:
                    repeat_read = True
            if not repeat_read:
                continue

            inner_reads.append(read_aln[0].overlap.cur_id)
            for prev_edge, next_edge in zip(read_aln[:-1], read_aln[1:]):
                if (prev_edge.edge_id in inputs and
                        next_edge.edge_id == path[0].edge_id):
                    input_reads[prev_edge.edge_id].append(prev_edge.overlap.cur_id)

                if (prev_edge.edge_id == path[-1].edge_id and
                        next_edge.edge_id in outputs):
                    output_reads[next_edge.edge_id].append(next_edge.overlap.cur_id)

        if (not len(inner_reads) or len(input_reads) != MULT or
                len(output_reads) != MULT):
            continue

        #add edges sequences:
        sequences = {}
        for edge in chain(input_reads, output_reads):
            seq_id = repeat_graph.edges[edge].edge_sequences[0].edge_seq_name
            seq = edge_seqs[seq_id[1:]]
            if seq_id[0] == "-":
                seq = fp.reverse_complement(seq)
            sequences[edge] = seq

        template_seq = ""
        for edge in path:
            seq_id = edge.edge_sequences[0].edge_seq_name
            seq = edge_seqs[seq_id[1:]]
            if seq_id[0] == "-":
                seq = fp.reverse_complement(seq)
            template_seq += seq
        sequences["template"] = template_seq

        #print path_id
        #for h, s in sequences.items():
        #    print h, s[:100]

        repeats_dict[path_id] = RepeatInfo(path_id, [e.edge_id for e in path],
                                           inner_reads, input_reads, output_reads,
                                           sequences, MULT)

    return repeats_dict

def maybe_convert_array_to_dask(array_type):
    # If one uses dask for PCA it will always require dask-ml.
    # dask-ml can’t do 2D-chunked arrays, so rechunk them.
    if as_dask_array := DASK_CONVERTERS.get(array_type):
        return (as_dask_array,)

    # When not using dask, just return the array type
    assert "dask" not in array_type.__name__, "add more branches or refactor"
    return (array_type,)

