def generate_contigs(args, run_params, graph_edges, out_folder,
                    log_file, config_file, repeat_graph, reads_alignment):
    logger.debug("-----Begin contigger analyser log------")

    cmdline = [CONTIGGER_BIN, "contigger", "--graph-edges", graph_edges,
               "--reads", ",".join(args.reads), "--out-dir", out_folder,
               "--config", config_file, "--repeat-graph", repeat_graph,
               "--graph-aln", reads_alignment, "--log", log_file,
               "--threads", str(args.threads)]
    if args.debug:
        cmdline.append("--debug")
    if args.keep_haplotypes:
        cmdline.append("--no-scaffold")
    #if args.kmer_size:
    #    cmdline.extend(["--kmer", str(args.kmer_size)])
    cmdline.extend(["--min-ovlp", str(run_params["min_overlap"])])

    if args.extra_params:
        cmdline.extend(["--extra-params", args.extra_params])

    try:
        logger.debug("Running: " + " ".join(cmdline))
        subprocess.check_call(cmdline)
    except subprocess.CalledProcessError as e:
        if e.returncode == -9:
            logger.error("Looks like the system ran out of memory")
        raise RepeatException(str(e))
    except OSError as e:
        raise RepeatException(str(e))

def create_10x_feature_barcode_map(out_path: str) -> str:
    """Dry version of `utils.create_10x_feature_barcode_map`.
    """
    chemistry = ngs.chemistry.get_chemistry('10xFB')
    gex = chemistry.chemistry('gex')
    fb = chemistry.chemistry('fb')
    if PLATFORM == 'windows':
        raise UnsupportedOSError(
            "10x Feature Barcode dry run is not supported on Windows. "
            f"Please manually combine {fb.whitelist_path} and {gex.whitelist_path} "
            "into a TSV with the former as the first column and the latter as the second."
        )
    elif PLATFORM == 'linux':
        print(
            f'paste <(zcat {fb.whitelist_path}) <(zcat {gex.whitelist_path}) > {out_path}'
        )
    elif PLATFORM == 'darwin':
        print(
            f'paste <(gzcat {fb.whitelist_path}) <(gzcat {gex.whitelist_path}) > {out_path}'
        )
    else:
        raise UnsupportedOSError(f'Unrecognized platform {PLATFORM}')
    return out_path

def get_circular_component(self, circular_pseudotime):
    if self.n_circular_unit == 1:
        return numpy.hstack([numpy.sin(circular_pseudotime),
                             numpy.cos(circular_pseudotime)]) @ self.get_circular_loadings()
    else:
        temp = []
        for i in range(self.n_circular_unit):
            temp.append(numpy.sin(circular_pseudotime[:, [i]]))
            temp.append(numpy.cos(circular_pseudotime[:, [i]]))
        return numpy.hstack(temp) @ self.get_circular_loadings()

