def log_likelihood(
    x: torch.Tensor, mu: torch.Tensor, log_var: torch.Tensor
) -> torch.Tensor:
    return -0.5 * (
        torch.square(x - mu) / torch.exp(log_var) + math.log(2 * math.pi) + log_var
    )

