def _fatal_errors(jerr):
    if jerr == 7777:
        raise ValueError(
            "All predictors have zero variance " "(glmnet error no. 7777)."
        )

    if jerr == 10000:
        raise ValueError(
            "At least one value of relative_penalties must be "
            "positive (glmnet error no. 10000)."
        )

    if jerr == 90000:
        raise ValueError("Solver did not converge (glmnet error no. 90000).")

    if jerr < 7777:
        raise RuntimeError(
            "Memory allocation error (glmnet error no. {}).".format(jerr)
        )

    if jerr > 8000 and jerr < 9000:
        k = jerr - 8000
        raise ValueError("Probability for class {} close to 0.".format(k))

    if jerr > 9000:
        k = jerr - 9000
        raise ValueError("Probability for class {} close to 1.".format(k))

    else:
        raise RuntimeError("Fatal glmnet error no. {}.".format(jerr))

def get_peak_sequences(adata, genome):

    genome = SeqIO.to_dict(SeqIO.parse(genome, format="fasta"))

    tmp = []
    for row in adata.var.to_dict("records"):

        try:
            seq = get_sequence(chrom=row["chr"], start=row["start"], end=row["stop"], genome=genome)
        except KeyError:
            seq = np.nan

        tmp.append(seq)

    adata.var["seq"] = tmp

def _reassign_muts(self, tree_idx, subclone_idx_map, destination='best'):
  deleted_muts = []
  mutass = self._mutass[tree_idx]

  for sidx in sorted(subclone_idx_map.keys()):
    new_idx = subclone_idx_map[sidx]
    # This ensures we're not improperly overwriting assignments.
    assert new_idx < sidx

    if new_idx is None: # Node was removed.
      # This will comprise both SSMs and CNVs.
      deleted_muts.append(mutass[sidx])
    else:
      mutass[new_idx] = mutass[sidx]
    del mutass[sidx]

  for dm in deleted_muts:
    if destination == 'best':
      self._move_muts_to_best_node(dm, mutass, self._tree_summaries[tree_idx]['populations'])
    elif destination == 'clonal':
      self._move_muts_to_clonal_node(dm, mutass, self._tree_summaries[tree_idx]['populations'], self._tree_summaries[tree_idx]['structure'])
    else:
      raise Exception('Unknown destination: %s' % destination)

def haplotypes(self):
  """Returns the haplotypes list[str] of our candidate_haplotypes."""
  return self.candidate_haplotypes.haplotypes

def _correct_mut_counts(self, populations, tree_idx):
  for sidx, subclone in populations.items():
    # Note that only mutass entries for subclones with (> 0 SSMs or > 0
    # CNVs) will exist. Thus, no mutass entry will exist for node 0, as it
    # never has SSMs or CNVs.
    if sidx == 0:
      continue
    for mut_type in ('ssms', 'cnvs'):
      subclone['num_%s' % mut_type] = len(self._mutass[tree_idx][sidx][mut_type])

def _list_mutations(self, tree, include_ssm_names, cnv_logical_physical_mapping):
  cnvs = {}
  ssms = {}
  ssms_in_cnvs = defaultdict(list)

  def _traverse(node):
    for mut in node['node'].get_data():
      if mut.id.startswith('s'):
        ssms[mut.id] = {
          'ref_reads': mut.a,
          'total_reads': mut.d,
          'expected_ref_in_ref': mut.mu_r,
          'expected_ref_in_variant': mut.mu_v
        }
        if include_ssm_names:
          ssms[mut.id]['name'] = mut.name

        for cnv, maternal_cn, paternal_cn in mut.cnv:
          ssms_in_cnvs[cnv.id].append({
            'ssm_id': mut.id,
            'maternal_cn': maternal_cn,
            'paternal_cn': paternal_cn,
          })
      elif mut.id.startswith('c'):
        cnvs[mut.id] = {
          'ref_reads': mut.a,
          'total_reads': mut.d,
          'physical_cnvs': cnv_logical_physical_mapping[mut.id]
        }
      else:
        raise Exception('Unknown mutation type: %s' % mut.id)
    for child in node['children']:
      _traverse(child)
  _traverse(tree.root)

  for cnv_id, cnv in cnvs.items():
    cnv['ssms'] = ssms_in_cnvs[cnv_id]

  return {
    'ssms': ssms,
    'cnvs': cnvs,
  }

def build_supervised_layer(supervision_metric, Y, name='supervised'):
    """Constructs a dense layer suitable for the requested supervision metric and labels."""

    SupervisedDense = partial(Dense, name=name)
    SvmDense = partial(SupervisedDense, activation='linear', kernel_regularizer=regularizers.l2())

    # Regression
    if not is_categorical(supervision_metric):
        n_classes = Y.shape[-1] if len(Y.shape) > 1 else 1
        return SupervisedDense(n_classes, activation='linear')

    # Multiclass classification
    if is_multiclass(supervision_metric):
        if is_hinge(supervision_metric):
            # Multiclass Linear SVM layer
            n_classes = len(np.unique(Y, axis=0))
            return SvmDense(n_classes)
        # Softmax classifier
        validate_sparse_labels(Y)
        n_classes = len(np.unique(Y[Y != np.array(-1)]))
        return SupervisedDense(n_classes, activation='softmax')

    # Binary classification
    n_classes = Y.shape[-1] if len(Y.shape) > 1 else 1
    if is_hinge(supervision_metric):
        # Binary Linear SVM layer
        return SvmDense(n_classes)
    # Binary logistic classifier
    return SupervisedDense(n_classes, activation='sigmoid')

