def triplet_loss(distance='pn'):
    """Returns a previously registered triplet loss function associated
    with the string 'distance'. If passed a callable, just returns it."""
    if callable(distance):
        return distance
    try:
        loss_fn = loss_dict[distance]
        return loss_fn
    except KeyError:
        raise ValueError("Loss function {} not registered with ivis".format(distance))

def __call__(self, y_true, y_pred):
    anchor, positive, negative = tf.unstack(y_pred)
    return K.mean(K.maximum(self._euclidean_distance(anchor, positive) - self._euclidean_distance(anchor, negative) + self.margin, 0))

def __call__(self, y_true, y_pred):
    anchor, positive, negative = tf.unstack(y_pred)
    return K.mean(K.maximum(cosine_distance(anchor, positive) - cosine_distance(anchor, negative) + self.margin, 0))

def _calc_read_counts(self, variant):
  if not ('t_alt_count' in variant.INFO and 't_ref_count' in variant.INFO):
    raise ReadCountsUnavailableError()
  assert len(variant.INFO['t_alt_count']) == len(variant.INFO['t_ref_count']) == 1

  alt_reads = int(variant.INFO['t_alt_count'][0])
  ref_reads = int(variant.INFO['t_ref_count'][0])
  total_reads = alt_reads + ref_reads
  # Some variants havezero alt and ref reads.
  if total_reads == 0:
    raise ReadCountsUnavailableError()
  return (ref_reads, total_reads)

