def background_distribution(adata):

    seq_concat = "".join([seq for seq in adata.var.seq if not pd.isna(seq)])

    counts = np.zeros(4)

    idx = {
        "A": 0,
        "a": 0,
        "C": 1,
        "c": 1,
        "G": 2,
        "g": 2,
        "T": 3,
        "t": 3
    }

    for base in seq_concat:
        if base in idx:
            counts[idx[base]] += 1

    bg = counts / counts.sum()
    bg = {base: frac for base, frac in zip(["A", "C", "G", "T"], bg)}

    return bg

