def identify_cluster_ATAC(adata, cell_type, cell_type_markers, peak_promoter_file, gene_name_pos=5, path='', n_peaks_per_cluster=1000):

    peak_name = []
    gene_name = []
    with open(path+peak_promoter_file) as f:
        head = f.readline()
        for line in f:
            line = line.split("\t")
            peak_name.append(line[0])
            gene_name.append(line[gene_name_pos].upper())

    matching_peaks = []
    matching_gene_name = []
    for i in range(0,len(peak_name)):
        # check if peak is in the adata object and if the according gene name is a marker
        if peak_name[i] in list(adata.var_names) and gene_name[i] in cell_type_markers[cell_type]:
            matching_peaks.append(peak_name[i])
            matching_gene_name.append(gene_name[i])
    # get the cell type names per matching peak
    cell_type_peaks = {}
    cell_type_peaks[cell_type] = []
    for j in range(0,len(matching_peaks)):
        if matching_gene_name[j] in cell_type_markers[cell_type]:
            cell_type_peaks[cell_type].append(matching_peaks[j]+"_"+matching_gene_name[j])

    # make the peaks unique
    cell_type_peaks[cell_type] = list(set(cell_type_peaks[cell_type]))


    cell_type_peak = []
    cell_type_gene = []
    for elem in cell_type_peaks[cell_type]:
        ctype = elem.split("_")
        cell_type_peak.append(ctype[0]+"_"+ctype[1]+"_"+ctype[2])
        cell_type_gene.append(ctype[3])

    sc.tl.rank_genes_groups(adata, groupby="louvain", n_genes=n_peaks_per_cluster)

    # top 100 to 1000 ranked peaks per louvain group
    ATAC_ranking_dict = {}
    for group in range(0, len(set(list(adata.obs["louvain"])))):
        ATAC_ranking_dict[str(group)] = []
        for idx in range(0,n_peaks_per_cluster):
            ATAC_ranking_dict[str(group)].append(list(adata.uns["rank_genes_groups"]['names'])[idx][group])

    sig_markers = []
    sig_peak = []
    for group in range(0, len(set(list(adata.obs["louvain"])))):
        for elem in ATAC_ranking_dict[str(group)]:
            if elem in cell_type_peak:
                sig_markers.append(elem+":"+str(group))
                sig_peak.append(elem)                

    if len(sig_markers) > 200:
        print("WARNING: found more than 200 marker peaks for your chosen cell type. Consider choosing a smaller number for n_peaks_per_cluster to reduce running time and get more significant results.")

    group_contribution = []
    for element in sig_markers:
        group = element.split(":")[1]
        group_contribution.append(group)

    most_prominent = max(set(group_contribution), key = group_contribution.count) 

    print("Differentially open peaks in promoters for known",cell_type,"marker genes are most prominently found in louvain group",most_prominent)

    # only take unique peaks (peaks can be among top markers in more than one group)
    unique_sig_peaks = []
    sig_gene_names = []
    for idx,name in enumerate(cell_type_peak):
        if name in sig_peak:
            sig_gene_names.append(cell_type_gene[idx])
            unique_sig_peaks.append(cell_type_peak[idx])

    return(sc.pl.umap(adata, color=unique_sig_peaks, title=sig_gene_names))

def peak_bg_kmers(adata, kmer_size, genome):

    shift_left = int(np.floor(kmer_size / 2))
    shift_right = int(np.ceil(kmer_size / 2))

    kmers = defaultdict(int)
    for row in adata.var.to_dict("records"):

        try:
            seq = get_sequence(row["chr"], row["start"] - shift_left, row["stop"] + shift_right + 1, genome=genome)
        except KeyError:
            continue

        for i in range(shift_left, len(seq) - shift_right):
            window_start = i - shift_left
            window_stop = i + shift_right
            kmer = seq[window_start:window_stop]
            kmers[kmer] += 1

    return kmers

def Jacobian_kovf(
    x: np.ndarray, fjac_base: Callable, K: np.ndarray, Q: np.ndarray, exact: bool = False, mu: Optional[float] = None
) -> np.ndarray:
    """analytical Jacobian for RKHS vector field functions with Gaussian kernel.

    Args:
        x: Coordinates where the Jacobian is evaluated.
        vf_dict:
            A dictionary containing RKHS vector field control points, Gaussian bandwidth,
            and RKHS coefficients.
            Essential keys: 'X_ctrl', 'beta', 'C'

    Returns:
        Jacobian matrices stored as d-by-d-by-n numpy arrays evaluated at x.
            d is the number of dimensions and n the number of coordinates in x.
    """
    if K.ndim == 1:
        K = np.diag(K)

    if exact:
        if mu is None:
            raise Exception("For exact calculations of the Jacobian, the mean of the PCA transformation is needed.")

        s = np.sign(x @ Q.T + mu)
        if x.ndim > 1:
            G = np.zeros((Q.shape[1], Q.shape[1], x.shape[0]))
            KQ = K @ Q
            # KQ = (np.diag(K) * Q.T).T
            for i in range(x.shape[0]):
                G[:, :, i] = s[i] * Q.T @ KQ
        else:
            G = s * Q.T @ K @ Q
    else:
        G = Q.T @ K @ Q
        if x.ndim > 1:
            G = np.repeat(G[:, :, None], x.shape[0], axis=2)

    return fjac_base(x) - G

def nCr(self, n, r):
    f = math.factorial
    return f(n) / f(r) / f(n - r)

def Calc_chr_count(self, barcode):
    AC = 0
    AN = 0
    for c in barcode[1:-1]:
        if c == 'X':
            continue
        else:
            AN += 2
            AC += int(c)
    AF = float(AC) / AN
    return (AC, AF, AN)

def resolve_block_groups(svtype, svcands, groups_initial, config):
    """For clustering groups of SVs for combining .snfs (multi-call)"""

    # TODO: Remove sorting
    groups = groups_initial
    for svcand in sorted(svcands, key=lambda cand: cand.support, reverse=True):
        best_group = None
        best_dist = math.inf

        if svtype == "BND":
            mate_contig, mate_ref_start = svcand.bnd_info.mate_contig, svcand.bnd_info.mate_ref_start
            for group in groups:
                # TODO: Favor bigger groups in placement
                dist = abs(group.pos_mean - svcand.pos) + abs(group.bnd_mate_ref_start_mean - mate_ref_start)
                if dist < best_dist and dist <= config.cluster_merge_bnd * 2 and group.bnd_mate_contig == mate_contig:
                    if not config.combine_separate_intra or svcand.sample_internal_id not in group.included_samples:
                        best_group = group
                        best_dist = dist
        else:
            for group in groups:
                # TODO: Favor bigger groups in placement
                dist = abs(group.pos_mean - svcand.pos) + abs(abs(group.len_mean) - abs(svcand.svlen))  # check if group.pos_mean is updated or stays the same for the first SV starting the group
                minlen = float(min(abs(group.len_mean), abs(svcand.svlen)))
                if minlen > 0 and dist < best_dist and dist <= config.combine_match * math.sqrt(minlen) and dist <= config.combine_match_max:
                    if (not config.combine_separate_intra or svcand.sample_internal_id not in group.included_samples) and group.align_call(svcand, config.combine_pctseq):
                        best_group = group
                        best_dist = dist

        if best_group is None:
            groups.append(
                sv.SVGroup.from_candidate(svcand)
            )
        else:
            best_group.add_candidate(svcand)
    return groups

