def load_tandem_repeats(filename, padding):
    contigs_tr = {}
    unsorted = False
    with open(filename, "r") as handle:
        for line in handle:
            parts = line.split("\t")
            if len(parts) >= 3:
                contig, start, end = parts[:3]
                start = int(start)
                end = int(end)
                if contig not in contigs_tr:
                    contigs_tr[contig] = []
                if len(contigs_tr[contig]) > 0:
                    last_start, last_end = contigs_tr[contig][-1]
                    if start < last_start:
                        unsorted = True
                contigs_tr[contig].append((max(0, int(start) - padding), int(end) + padding))

    if unsorted:
        print("Info: The tandem repeat annotations file was not sorted. Sorting it in-memory after loading... (please sort the .bed file once before to save time when running multiple samples)")
        sort_start = time.time()
        for contig in contigs_tr:
            contigs_tr[contig].sort()
        print(f"Info: Optional sorting of input tandem repeat annotations took {time.time() - sort_start:.2f}s.")

    return contigs_tr

def make_labeler_ref(self, candidates, true_variants, bufsize=20):
  all_variants = candidates + true_variants
  contig = all_variants[0].reference_name
  start = min(x.start for x in all_variants)
  end = max(x.end for x in all_variants)
  contig_nbp = self._ref_reader.contig(contig).n_bases
  region = ranges.make_range(
      contig, max(start - 1, 0), min(end + bufsize, contig_nbp)
  )
  ref_bases = self._ref_reader.query(region)
  return ReferenceRegion(ref_bases, start=region.start)

