def read_model(self):
    """Read the model and the couplings from the model file."""
    if self.verbosity > 0:
        settings.m(0, "reading model", self.model)
    # read model
    boolRules = []
    for line in self.model.open():
        if line.startswith("#") and "modelType =" in line:
            keyval = line
            if "|" in line:
                keyval, type = line.split("|")[:2]
            self.modelType = keyval.split("=")[1].strip()
        if line.startswith("#") and "invTimeStep =" in line:
            keyval = line
            if "|" in line:
                keyval, type = line.split("|")[:2]
            self.invTimeStep = float(keyval.split("=")[1].strip())
        if not line.startswith("#"):
            boolRules.append([s.strip() for s in line.split("=")])
        if line.startswith("# coupling list:"):
            break
    self.dim = len(boolRules)
    self.boolRules = dict(boolRules)
    self.varNames = {s: i for i, s in enumerate(self.boolRules.keys())}
    names = self.varNames
    # read couplings via names
    self.Coupl = np.zeros((self.dim, self.dim))
    boolContinue = True
    for (
        line
    ) in self.model.open():  # open(self.model.replace('/model','/couplList')):
        if line.startswith("# coupling list:"):
            boolContinue = False
        if boolContinue:
            continue
        if not line.startswith("#"):
            gps, gs, val = line.strip().split()
            self.Coupl[int(names[gps]), int(names[gs])] = float(val)
    # adjancecy matrices
    self.Adj_signed = np.sign(self.Coupl)
    self.Adj = np.abs(np.array(self.Adj_signed))
    # build bool coefficients (necessary for odefy type
    # version of the discrete model)
    self.build_boolCoeff()

def _choose_graph(
    adata: AnnData, obsp: str | None, neighbors_key: str | None
) -> CSBase:
    """Choose connectivities from neighbors or another obsp entry."""
    if obsp is not None and neighbors_key is not None:
        msg = "You can't specify both obsp, neighbors_key. Please select only one."
        raise ValueError(msg)

    if obsp is not None:
        return adata.obsp[obsp]
    else:
        neighbors = NeighborsView(adata, neighbors_key)
        if "connectivities" not in neighbors:
            msg = (
                "You need to run `pp.neighbors` first to compute a neighborhood graph."
            )
            raise ValueError(msg)
        return neighbors["connectivities"]

def autodevice() -> torch.device:
    r"""
    Get torch computation device automatically
    based on GPU availability and memory usage

    Returns
    -------
    device
        Computation device
    """
    used_device = -1
    try:
        pynvml.nvmlInit()
        free_mems = np.array(
            [
                pynvml.nvmlDeviceGetMemoryInfo(
                    pynvml.nvmlDeviceGetHandleByIndex(i)
                ).free
                for i in range(pynvml.nvmlDeviceGetCount())
            ]
        )
        if free_mems.size:
            best_devices = np.where(free_mems == free_mems.max())[0]
            used_device = np.random.choice(best_devices, 1)[0]
    except pynvml.NVMLError:
        pass
    if used_device == -1:
        logger.info("Using CPU as computation device.")
        return torch.device("cpu")
    logger.info("Using GPU %d as computation device.", used_device)
    os.environ["CUDA_VISIBLE_DEVICES"] = str(used_device)
    return torch.device("cuda")

def dfs(start_vertex, connected_components_counter):
    dfs_stack = [start_vertex]
    used[start_vertex] = True
    while len(dfs_stack):
        vertex = dfs_stack.pop()
        connected_components[vertex] = connected_components_counter
        for neighbour in graph[vertex]:
            if not used[neighbour]:
                dfs_stack.append(neighbour)
                used[neighbour] = True

def other_cells_genotype_prob(self, gt_flag, nCr_matrix):
    if self.other_cell_list_len == 0:
        return 1
    else:
        prob = 0.0
        for l in range(0, self.residual_mat.dim[0]):
            coeff = self.find_coeff(self.n_cells, l, gt_flag, nCr_matrix)
            prob = prob + coeff * self.residual_mat.denom_prob_matrix[
                l, self.residual_mat.dim[1] - 1] * self.prior_variant_allele[l + gt_flag]
        return prob

