def Calc_chr_count(self, barcode):
    AC = 0
    AN = 0
    for c in barcode[1:-1]:
        if c == 'X':
            continue
        else:
            AN += 2
            AC += int(c)
    AF = float(AC) / AN
    return (AC, AF, AN)

