def get_first_conv_layer(layers, get_act=False):
    """Return the first convolutional layers in a stack of layer.

    Parameters
    ----------
    layers: list
        List of Keras layers.
    get_act: bool
        Return the activation layer after the convolutional weight layer.

    Returns
    -------
    Keras layer
        Convolutional layer or tuple of convolutional layer and activation layer
        if `get_act=True`.
    """
    conv_layer = None
    act_layer = None
    for layer in layers:
        if isinstance(layer, kl.Conv1D) and layer.input_shape[-1] == 4:
            conv_layer = layer
            if not get_act:
                break
        elif conv_layer and isinstance(layer, kl.Activation):
            act_layer = layer
            break
    if not conv_layer:
        raise ValueError('Convolutional layer not found')
    if get_act:
        if not act_layer:
            raise ValueError('Activation layer not found')
        return (conv_layer, act_layer)
    else:
        return conv_layer

def load_obo(
    cls, file: str
) -> "CellTypeDAG":  # Only building on "is_a" relation between CL terms
    import pronto

    ont = pronto.Ontology(file)
    graph, vdict = igraph.Graph(directed=True), {}
    for item in ont:
        if not item.id.startswith("CL"):
            continue
        if "is_obsolete" in item.other and item.other["is_obsolete"][0] == "true":
            continue
        graph.add_vertex(
            name=item.id,
            cell_ontology_class=item.name,
            desc=str(item.desc),
            synonyms=[(f"{syn.desc} ({syn.scope})") for syn in item.synonyms],
        )
        assert item.id not in vdict
        vdict[item.id] = item.id
        assert item.name not in vdict
        vdict[item.name] = item.id
        for synonym in item.synonyms:
            if synonym.scope == "EXACT" and synonym.desc != item.name:
                vdict[synonym.desc] = item.id
    for source in graph.vs:  # pylint: disable=not-an-iterable
        for relation in ont[source["name"]].relations:
            if relation.obo_name != "is_a":
                continue
            for target in ont[source["name"]].relations[relation]:
                if not target.id.startswith("CL"):
                    continue
                graph.add_edge(
                    source["name"],
                    graph.vs.find(name=target.id.split()[0])[
                        "name"
                    ],  # pylint: disable=no-member
                )
                # Split because there are many "{is_infered...}" suffix,
                # falsely joined to the actual id when pronto parses the
                # obo file
    return cls(graph, vdict)

