def get_supervised_similarity(
    all_labels: typing.List[str], cluster: np.ndarray, sum_cluster: int
) -> np.ndarray:
    similarity = np.zeros((sum_cluster, sum_cluster))
    for i in range(sum_cluster):
        for j in range(sum_cluster):
            if list(all_labels[cluster == i])[0] == list(all_labels[cluster == j])[0]:
                similarity[i, j] = 1

    return similarity

def preprocess(
    x: torch.Tensor, libs: torch.Tensor, noisy: bool = True
) -> torch.Tensor:
    x = x / (libs / 10000)
    if noisy:
        x = D.Poisson(rate=x).sample()
    x = x.log1p()
    return x

def _mnn_mask(d: torch.Tensor, k: int) -> torch.Tensor:
    return (
        MNNAdversarial._neighbor_mask(d, k)
        & MNNAdversarial._neighbor_mask(d.T, k).T
    )

