def reset_parameters(self):
    # change initializers
    if self.trunc:
        for _weight in self.weight:
            nn.init.trunc_normal_(
                _weight,
                std=self.init_std,
                a=-2 * self.init_std,
                b=2 * self.init_std,
            )
    else:
        for _weight in self.weight:
            nn.init.normal_(_weight, std=self.init_std)
    if self.bias is not None:
        nn.init.zeros_(self.bias)

def forward(self, x: torch.Tensor) -> torch.Tensor:
    gau = self.gau(self.mlp(x))
    return gau, gau

def get_config(self):
    return {'name': self.__class__.__name__,
            'l': float(self.l),
            'p': float(self.p)}

def _convergence_errors(jerr):
    if jerr < -20000:
        k = abs(20000 + jerr)
        warnings.warn(
            "Predicted probability close to 0 or 1 for " "lambda no. {}.".format(k),
            RuntimeWarning,
        )

    if jerr > -20000 and jerr < -10000:
        # This indicates the number of non-zero coefficients in a model
        # exceeded a user-specified bound. We don't expose this parameter to
        # the user, so there is not much sense in exposing the error either.
        warnings.warn("Non-fatal glmnet error no. {}.".format(jerr), RuntimeWarning)

    if jerr > -10000:
        warnings.warn(
            "Model did not converge for smaller values of lambda, "
            "returning solution for the largest {} values.".format(-1 * (jerr - 1)),
            RuntimeWarning,
        )

def _calculate_af(self, support: int, coverage: int) -> float:
    """
    Calculate allele fraction
    """
    return support / float(coverage)

def gan_d_loss(
    y: torch.Tensor, y_hat: torch.Tensor, eps: float = 1e-8
) -> torch.Tensor:
    return -(torch.log(y_hat + eps) + torch.log(1 - y + eps)).mean()

def best_leaves(
    self, thresh: float = 0.5, min_path: int = 4, retrieve: str = "name"
) -> typing.List[str]:
    subgraph = self.graph.subgraph(self.graph.vs.select(value_gt=thresh))
    leaves, max_value = [], 0
    for leaf in subgraph.vs.select(lambda v: v.indegree() == 0):
        if self.longest_paths_to_root(leaf["name"]) < min_path:
            continue
        if leaf["value"] > max_value:
            max_value = leaf["value"]
            leaves = [leaf[retrieve]]
        elif leaf["value"] == max_value:
            leaves.append(leaf[retrieve])
    return leaves

