def _get_samples(v):
    import numpy as np

    def _get_gt(s):
        if not ":" in s:
            return 2
        s = s.split(":", 1)[0]
        if s in ("0/0", "0|0", "0/.", "./0", "0|."):
            return 0
        if s in ("0/1", "0|1", "1/.", "./1", "1/."):
            return 1
        if s in ("1/1", "1|1"):
            return 3
        return 2
    toks = _get_line_for(v)
    samples = toks[9:]
    return np.array([_get_gt(s) for s in samples], np.int32)

def __init__(self, intervals):
    self.intervals = collections.defaultdict(list)
    self.max_len = {}

    for i, iv in enumerate(intervals):
        self.intervals[iv.chrom].append(iv)
    for chrom in self.intervals:
        self.intervals[chrom].sort(key=operator.attrgetter('start'))
        self.max_len[chrom] = max(1, max([i.end - i.start for i in self.intervals[chrom]]))

def _get_empirical(
    self, n_jobs: int, random_seed: int
) -> np.ndarray:  # n_models * [n_clusters * n_empirical]
    if self.empirical is None:
        utils.logger.info("Generating empirical null distributions...")
        if not self.cluster_empirical:
            self.cluster = np.zeros((self.ref.shape[0], len(self)), dtype=int)
        latent = self._get_latent(n_jobs)
        cluster = self._get_cluster(n_jobs)
        rs = np.random.RandomState(random_seed)
        bg = rs.choice(latent.shape[0], size=self.n_empirical)
        if self.distance_metric is not ed:
            bg_posterior = self._get_posterior(n_jobs, random_seed, idx=bg)
        self.empirical = []
        dist_kws = {"eps": self.eps} if self.eps is not None else {}
        if self.distance_metric is amd:
            dist_kws["x_is_pcasd"] = True
            dist_kws["y_is_pcasd"] = True
        for k in range(len(self)):  # model_idx
            empirical = np.zeros((np.max(cluster[:, k]) + 1, self.n_empirical))
            for c in np.unique(cluster[:, k]):  # cluster_idx
                fg = rs.choice(
                    np.where(cluster[:, k] == c)[0], size=self.n_empirical
                )
                if self.distance_metric is ed:
                    empirical[c] = np.sort(
                        joblib.Parallel(n_jobs=n_jobs, backend="threading")(
                            joblib.delayed(self.distance_metric)(
                                latent[fg[i]], latent[bg[i]]
                            )
                            for i in range(self.n_empirical)
                        )
                    )
                else:
                    fg_posterior = self._get_posterior(n_jobs, random_seed, idx=fg)
                    empirical[c] = np.sort(
                        joblib.Parallel(n_jobs=n_jobs, backend="threading")(
                            joblib.delayed(self.distance_metric)(
                                latent[fg[i], k],
                                latent[bg[i], k],
                                fg_posterior[i][k],
                                bg_posterior[i][k],
                                **dist_kws,
                            )
                            for i in range(self.n_empirical)
                        )
                    )
            self.empirical.append(empirical)
    return self.empirical

def run(self):
    print("# cyvcf2: htslib mode is {}".format(CYVCF2_HTSLIB_MODE))
    if CYVCF2_HTSLIB_MODE == "BUILTIN" or not check_libhts():
        if platform.system() == "Windows":
            # Windows htslib can't be built internall
            raise RuntimeError(
                "Required library 'hts-3.dll' not found. Please install htslib first."
            )

        print(
            "# cyvcf2: htslib configure options is {}".format(
                CYVCF2_HTSLIB_CONFIGURE_OPTIONS
            )
        )
        build_htslib(
            CYVCF2_HTSLIB_CONFIGURE_OPTIONS, CYVCF2_HTSLIB_MODE == "BUILTIN"
        )

    if CYVCF2_HTSLIB_MODE == "BUILTIN":
        # add htslib linked libraries
        # libcrypto is bundled with libssl, capabale to replace libssl
        all_dynamic_libs = {
            "z",
            "bz2",
            "lzma",
            "curl",
            "deflate",
            "crypto",
        }

        extra_libs = []
        # read the htslib config.status file to get the linked libraries
        with open(os.path.join("htslib", "config.status"), "r") as f:
            for line in f:
                if 'S["static_LIBS"]' in line:
                    linked_libs_str = line.split("=")[1].strip()[1:-1]
                    print("# cyvcf2: htslib librarys is {}".format(linked_libs_str))
                    linked_libs = linked_libs_str.split()
                    for lib in linked_libs:
                        if lib[2:] in all_dynamic_libs:  # remove -l prefix
                            extra_libs.append(lib[2:])

        self.extensions[0].libraries = self.extensions[0].libraries + extra_libs

    super().run()

def filter(
    self,
    by: str = "pval",
    cutoff: float = 0.05,
    model_tolerance: int = 0,
    n_jobs: int = 1,
) -> "Hits":
    r"""
    Filter hits by posterior distance or p-value

    Parameters
    ----------
    by
        Specifies a metric based on which to filter hits.
        Should be among {"dist", "pval"}.
    cutoff
        Cutoff when filtering hits.
    model_tolerance
        Maximal number of models allowed in which the cutoff is not
        satisfied, above which the query cell will be rejected.
        Irrelevant for reconciled hits.
    n_jobs
        Number of parallel jobs to run.

    Returns
    -------
    filtered_hits
        Hit object containing remaining hits after filtering
    """
    if by == "pval":
        assert self.pval is not None
        by = Hits.FILTER_BY_PVAL
    else:  # by == "dist"
        by = Hits.FILTER_BY_DIST
    if self.dist[0].ndim == 1:
        hits, dist, pval = [
            _
            for _ in zip(
                *joblib.Parallel(n_jobs=n_jobs, backend="threading")(
                    joblib.delayed(self._filter_reconciled_hits)(
                        _hits, _dist, _pval, by, cutoff
                    )
                    for _hits, _dist, _pval in zip(self.hits, self.dist, self.pval)
                )
            )
        ]
    else:
        hits, dist, pval = [
            _
            for _ in zip(
                *joblib.Parallel(n_jobs=n_jobs, backend="threading")(
                    joblib.delayed(self._filter_hits)(
                        _hits, _dist, _pval, by, cutoff, model_tolerance
                    )
                    for _hits, _dist, _pval in zip(self.hits, self.dist, self.pval)
                )
            )
        ]
    return Hits(self.blast, hits, dist, pval, self.query)

