def nearest_neighbor_accuracy(
    x: np.ndarray,
    y: np.ndarray,
    metric: str = "minkowski",
    similarity: typing.Callable = _identity,
    n_jobs: int = 1,
) -> float:
    nearestNeighbors = sklearn.neighbors.NearestNeighbors(
        n_neighbors=2, metric=metric, n_jobs=n_jobs
    )
    nearestNeighbors.fit(x)
    nni = nearestNeighbors.kneighbors(x, return_distance=False)
    return np.vectorize(similarity)(y, y[nni[:, 1].ravel()]).mean()

def neighbor_preservation_score(
    x: np.ndarray,
    nng: scipy.sparse.spmatrix,
    metric: str = "minkowski",
    k: typing.Union[int, float] = 0.01,
    n_jobs: int = 1,
) -> float:
    if not x.shape[0] == nng.shape[0] == nng.shape[1]:
        raise ValueError("Inconsistent shape!")
    n = x.shape[0]
    k = n * k if k < 1 else k
    k = np.round(k).astype(np.int)
    nn = sklearn.neighbors.NearestNeighbors(
        n_neighbors=min(n, k + 1), metric=metric, n_jobs=n_jobs
    ).fit(x)
    nni = nn.kneighbors(x, return_distance=False)[:, 1:]
    ap = np.array(
        [
            _average_precision(_nng.toarray().ravel()[_nni])
            for _nng, _nni in zip(nng, nni)
        ]
    )
    max_ap = np.array(
        [
            _average_precision(np.sort(_nng.toarray().ravel())[::-1][: nni.shape[1]])
            for _nng in nng
        ]
    )
    ap /= max_ap
    return ap.mean()

def get_unsupervised_similarity(
    similarity_latent: np.ndarray,
    num_batch: int,
    cluster: np.ndarray,
    sum_cluster: int,
    num_clusters: typing.List[int],
    volume: np.ndarray,
) -> typing.Tuple[np.ndarray]:
    center = np.zeros((sum_cluster, similarity_latent.shape[1]))
    for i in range(sum_cluster):
        center[i] = similarity_latent[cluster == i].mean(axis=0)

    raw_similarity = -pairwise_distances(
        center, metric=config.METRIC, **config.METRIC_KWARGS
    )

    if config.MNN:
        raw_similarity = get_MNN(
            num_batch, cluster, sum_cluster, num_clusters, raw_similarity
        )
    else:
        raw_similarity = (raw_similarity - config.THRESHOLD) / (1 - config.THRESHOLD)
        raw_similarity[raw_similarity < 0] = 0

    similarity = raw_similarity.copy()
    for i in range(sum_cluster):
        similarity[:, i] *= volume
        for j in range(num_batch):
            curr_sum = similarity[num_clusters[j] : num_clusters[j + 1], i].sum()
            if curr_sum > 0:
                similarity[num_clusters[j] : num_clusters[j + 1], i] /= curr_sum

    return similarity, raw_similarity

