def filter(
    self,
    by: str = "pval",
    cutoff: float = 0.05,
    model_tolerance: int = 0,
    n_jobs: int = 1,
) -> "Hits":
    r"""
    Filter hits by posterior distance or p-value

    Parameters
    ----------
    by
        Specifies a metric based on which to filter hits.
        Should be among {"dist", "pval"}.
    cutoff
        Cutoff when filtering hits.
    model_tolerance
        Maximal number of models allowed in which the cutoff is not
        satisfied, above which the query cell will be rejected.
        Irrelevant for reconciled hits.
    n_jobs
        Number of parallel jobs to run.

    Returns
    -------
    filtered_hits
        Hit object containing remaining hits after filtering
    """
    if by == "pval":
        assert self.pval is not None
        by = Hits.FILTER_BY_PVAL
    else:  # by == "dist"
        by = Hits.FILTER_BY_DIST
    if self.dist[0].ndim == 1:
        hits, dist, pval = [
            _
            for _ in zip(
                *joblib.Parallel(n_jobs=n_jobs, backend="threading")(
                    joblib.delayed(self._filter_reconciled_hits)(
                        _hits, _dist, _pval, by, cutoff
                    )
                    for _hits, _dist, _pval in zip(self.hits, self.dist, self.pval)
                )
            )
        ]
    else:
        hits, dist, pval = [
            _
            for _ in zip(
                *joblib.Parallel(n_jobs=n_jobs, backend="threading")(
                    joblib.delayed(self._filter_hits)(
                        _hits, _dist, _pval, by, cutoff, model_tolerance
                    )
                    for _hits, _dist, _pval in zip(self.hits, self.dist, self.pval)
                )
            )
        ]
    return Hits(self.blast, hits, dist, pval, self.query)

def get_population_AF(self, svcall: SVCall) -> tuple[float, int] | None:
    """
    Returns the population AF and population size for the given SVCall. Returns None if the variant is not found in the population SNF.
    """
    if svcall.contig not in self._blocks:
        self._blocks[svcall.contig] = self.get_all_blocks(svcall.contig)

    block = str(self._calculate_block_index(svcall.pos))
    best_dist = None
    best_variant = None
    try:
        for pv in self._blocks[svcall.contig][block][svcall.svtype]:
            pv: PopulationVariant
            dist = pv.match(svcall)
            if dist is not None:
                if best_dist is None or dist < best_dist:
                    best_dist = dist
                    best_variant = pv
    except KeyError:
        ...
    else:
        if best_variant is not None:
            return round(best_variant.af, 5), best_variant.genotyped_sample_count

    return None

