def gan_d_loss(
    y: torch.Tensor, y_hat: torch.Tensor, eps: float = 1e-8
) -> torch.Tensor:
    return -(torch.log(y_hat + eps) + torch.log(1 - y + eps)).mean()

def deviation_loss(self) -> torch.Tensor:
