def best_leaves(
    self, thresh: float = 0.5, min_path: int = 4, retrieve: str = "name"
) -> typing.List[str]:
    subgraph = self.graph.subgraph(self.graph.vs.select(value_gt=thresh))
    leaves, max_value = [], 0
    for leaf in subgraph.vs.select(lambda v: v.indegree() == 0):
        if self.longest_paths_to_root(leaf["name"]) < min_path:
            continue
        if leaf["value"] > max_value:
            max_value = leaf["value"]
            leaves = [leaf[retrieve]]
        elif leaf["value"] == max_value:
            leaves.append(leaf[retrieve])
    return leaves

def _get_nearest_neighbors(
    self, n_jobs: int
) -> typing.List[sklearn.neighbors.NearestNeighbors]:  # n_models
    if self.nearest_neighbors is None:
        latent = self._get_latent(n_jobs).swapaxes(0, 1)
        # NOTE: Makes cells discontiguous, but for nearest neighbor tree,
        # there's no influence on performance
        utils.logger.info("Fitting nearest neighbor trees...")
        self.nearest_neighbors = joblib.Parallel(
            n_jobs=min(n_jobs, len(self)), backend="loky"
        )(
            joblib.delayed(self._fit_nearest_neighbors)(_latent)
            for _latent in latent
        )
    return self.nearest_neighbors

def get_supervised_similarity(
    all_labels: typing.List[str], cluster: np.ndarray, sum_cluster: int
) -> np.ndarray:
    similarity = np.zeros((sum_cluster, sum_cluster))
    for i in range(sum_cluster):
        for j in range(sum_cluster):
            if list(all_labels[cluster == i])[0] == list(all_labels[cluster == j])[0]:
                similarity[i, j] = 1

    return similarity

def calc_reference_sas(
    adata: ad.AnnData,
    batch_effect: str = "dataset_name",
    cell_ontology: str = "cell_ontology_class",
    similarity: typing.Callable = _identity,
):
    neighbors_propotion = []
    n = len(adata.obs[batch_effect].unique())
    for x in adata.obs[batch_effect].unique():
        propotion = 0
        for i in adata.obs[cell_ontology].unique():
            neighbors = 0
            own_neighbors = 0
            for j in adata.obs[cell_ontology].unique():
                own_neighbors += (
                    similarity(i, j)
                    * (
                        (adata.obs[cell_ontology] == j) & (adata.obs[batch_effect] == x)
                    ).sum()
                )
                neighbors += similarity(i, j) * (adata.obs[cell_ontology] == j).sum()

            propotion += (
                own_neighbors
                / neighbors
                * (
                    (adata.obs[cell_ontology] == i) & (adata.obs[batch_effect] == x)
                ).sum()
            )

        propotion = propotion / (adata.obs[batch_effect] == x).sum()
        neighbors_propotion.append(propotion)
    neighbors_propotion = np.mean(neighbors_propotion)
    return 1 - (neighbors_propotion - 1 / n) / (1 - 1 / n)

