def nucleosome_signal(adata,
                      fragments,
                      n=10000):
    """
    Calculates the nucleosome signal (mononucleosomal to nucleosome-free ratio).

    Args:
        adata: AnnData
        fragments: path to fragments file
        n: number of cell-associated fragments to consider per barcode in AnnData

    Returns:
        None
    """

    n = adata.n_obs * n

    valid_bcs = set(adata.obs.index)

    comment = "#"
    check_for_comments = True
    use_strip = None

    fragment_info = {bc: [0, 0, []] for bc in valid_bcs}

    if fragments.endswith(".gz"):
        fh = gzip.open(fragments, mode="rt")
    else:
        fh = open(fragments, mode="r")

    c = 0

    for line in fh:

        if check_for_comments:
            if line.startswith(comment):
                continue
            else:
                check_for_comments = False

        if use_strip is None:
            line_split = line.strip().split("\t")
            if len(line_split) == 4:
                use_strip = True
            else:
                use_strip = False
        elif not use_strip:
            line_split = line.split("\t")
        else:
            line_split = line.strip().split("\t")

        bc = line_split[3]
        if bc not in valid_bcs:
            continue

        chrom = line_split[0]
        start = int(line_split[1])
        stop = int(line_split[2])

        length = stop - start
        if length < 147:
            fragment_info[bc][0] += 1
        elif length >= 147 and length < 294:
            fragment_info[bc][1] += 1

        fragment_info[bc][2].append(length)

        c += 1
        if c == n:
            break

    nucleosome_signal = dict()

    for bc, (nuc_free, mono_nuc, lns) in fragment_info.items():
        tmp = (
            mono_nuc / nuc_free if nuc_free != 0 else np.nan,
            lns
        )
        nucleosome_signal[bc] = tmp

    adata.obs["nucleosome_signal"] = [nucleosome_signal[bc][0] for bc in adata.obs.index]
    adata.uns["fragment_lengths"] = {bc: nucleosome_signal[bc][1] for bc in adata.obs.index}

def filter(
    self,
    by: str = "pval",
    cutoff: float = 0.05,
    model_tolerance: int = 0,
    n_jobs: int = 1,
) -> "Hits":
    r"""
    Filter hits by posterior distance or p-value

    Parameters
    ----------
    by
        Specifies a metric based on which to filter hits.
        Should be among {"dist", "pval"}.
    cutoff
        Cutoff when filtering hits.
    model_tolerance
        Maximal number of models allowed in which the cutoff is not
        satisfied, above which the query cell will be rejected.
        Irrelevant for reconciled hits.
    n_jobs
        Number of parallel jobs to run.

    Returns
    -------
    filtered_hits
        Hit object containing remaining hits after filtering
    """
    if by == "pval":
        assert self.pval is not None
        by = Hits.FILTER_BY_PVAL
    else:  # by == "dist"
        by = Hits.FILTER_BY_DIST
    if self.dist[0].ndim == 1:
        hits, dist, pval = [
            _
            for _ in zip(
                *joblib.Parallel(n_jobs=n_jobs, backend="threading")(
                    joblib.delayed(self._filter_reconciled_hits)(
                        _hits, _dist, _pval, by, cutoff
                    )
                    for _hits, _dist, _pval in zip(self.hits, self.dist, self.pval)
                )
            )
        ]
    else:
        hits, dist, pval = [
            _
            for _ in zip(
                *joblib.Parallel(n_jobs=n_jobs, backend="threading")(
                    joblib.delayed(self._filter_hits)(
                        _hits, _dist, _pval, by, cutoff, model_tolerance
                    )
                    for _hits, _dist, _pval in zip(self.hits, self.dist, self.pval)
                )
            )
        ]
    return Hits(self.blast, hits, dist, pval, self.query)

def predict_pseudotime(self, data: numpy.ndarray):
    res = keras.backend.function(inputs=[self.model.get_layer('input').input],
                                 outputs=[self.model.get_layer('embedding').output]
                                 )([data])
    return numpy.arctan2(res[0][:, 0], res[0][:, 1])

def load_obo(
    cls, file: str
) -> "CellTypeDAG":  # Only building on "is_a" relation between CL terms
    import pronto

    ont = pronto.Ontology(file)
    graph, vdict = igraph.Graph(directed=True), {}
    for item in ont:
        if not item.id.startswith("CL"):
            continue
        if "is_obsolete" in item.other and item.other["is_obsolete"][0] == "true":
            continue
        graph.add_vertex(
            name=item.id,
            cell_ontology_class=item.name,
            desc=str(item.desc),
            synonyms=[(f"{syn.desc} ({syn.scope})") for syn in item.synonyms],
        )
        assert item.id not in vdict
        vdict[item.id] = item.id
        assert item.name not in vdict
        vdict[item.name] = item.id
        for synonym in item.synonyms:
            if synonym.scope == "EXACT" and synonym.desc != item.name:
                vdict[synonym.desc] = item.id
    for source in graph.vs:  # pylint: disable=not-an-iterable
        for relation in ont[source["name"]].relations:
            if relation.obo_name != "is_a":
                continue
            for target in ont[source["name"]].relations[relation]:
                if not target.id.startswith("CL"):
                    continue
                graph.add_edge(
                    source["name"],
                    graph.vs.find(name=target.id.split()[0])[
                        "name"
                    ],  # pylint: disable=no-member
                )
                # Split because there are many "{is_infered...}" suffix,
                # falsely joined to the actual id when pronto parses the
                # obo file
    return cls(graph, vdict)

def load(cls, file: str) -> "CellTypeDAG":
    if file.endswith(".json"):
        return cls.load_json(file)
    elif file.endswith(".obo"):
        return cls.load_obo(file)
    else:
        raise ValueError("Unexpected file format!")

