def Jacobian_kovf(
    x: np.ndarray, fjac_base: Callable, K: np.ndarray, Q: np.ndarray, exact: bool = False, mu: Optional[float] = None
) -> np.ndarray:
    """analytical Jacobian for RKHS vector field functions with Gaussian kernel.

    Args:
        x: Coordinates where the Jacobian is evaluated.
        vf_dict:
            A dictionary containing RKHS vector field control points, Gaussian bandwidth,
            and RKHS coefficients.
            Essential keys: 'X_ctrl', 'beta', 'C'

    Returns:
        Jacobian matrices stored as d-by-d-by-n numpy arrays evaluated at x.
            d is the number of dimensions and n the number of coordinates in x.
    """
    if K.ndim == 1:
        K = np.diag(K)

    if exact:
        if mu is None:
            raise Exception("For exact calculations of the Jacobian, the mean of the PCA transformation is needed.")

        s = np.sign(x @ Q.T + mu)
        if x.ndim > 1:
            G = np.zeros((Q.shape[1], Q.shape[1], x.shape[0]))
            KQ = K @ Q
            # KQ = (np.diag(K) * Q.T).T
            for i in range(x.shape[0]):
                G[:, :, i] = s[i] * Q.T @ KQ
        else:
            G = s * Q.T @ K @ Q
    else:
        G = Q.T @ K @ Q
        if x.ndim > 1:
            G = np.repeat(G[:, :, None], x.shape[0], axis=2)

    return fjac_base(x) - G

def get_triplet_indices_generic(self, anchor_indices, neighbour_cands=None):
    """Slower, generic way of generating triplet indices that works on
    sequences, not just numpy arrays."""
    if neighbour_cands is None:
        neighbour_cands = self.get_all_neighbour_indices(anchor_indices)

    neighbour_indices = list(map(random.choice, neighbour_cands))
    negative_indices = self.gen_negative_indices_generic(neighbour_cands)
    return (anchor_indices, neighbour_indices, negative_indices)

def cl_accuracy(
    cl_dag: utils.CellTypeDAG,
    source: np.ndarray,
    target: np.ndarray,
    ref_cl_list: typing.List[str],  # a list of unique cl in ref
) -> pd.DataFrame:
    if len(source) != len(target):
        raise ValueError("Invalid input: different cell number.")
    positive_cl = []
    negative_cl = []
    for query_cl in np.unique(source):
        for ref_cl in ref_cl_list:
            if cl_dag.is_related(query_cl, ref_cl):
                positive_cl.append(query_cl)
                break
        else:
            negative_cl.append(query_cl)

    # sensitivity
    accuracy_dict = {}
    ref_cl_set = {cl_dag.get_vertex(item) for item in ref_cl_list}
    for query_cl in positive_cl:
        target_cl = target[source == query_cl]
        cl_accuracy = np.zeros(target_cl.size)
        cache = {}  # avoid repeated computation
        for i, _target_cl in enumerate(target_cl):
            if _target_cl in cache:
                cl_accuracy[i] = cache[_target_cl]
                continue
            if cl_dag.is_descendant_of(_target_cl, query_cl):
                cache[_target_cl] = 1  # equal or descendant results as 1
            elif cl_dag.is_ancestor_of(_target_cl, query_cl):
                intermediates = set.intersection(
                    set(
                        cl_dag.graph.bfsiter(
                            cl_dag.get_vertex(query_cl), mode=igraph.OUT
                        )
                    ),
                    set(
                        cl_dag.graph.bfsiter(
                            cl_dag.get_vertex(_target_cl), mode=igraph.IN
                        )
                    ),
                )
                cache[_target_cl] = np.mean(
                    [
                        len(list(cl_dag.graph.bfsiter(intermediate, mode=igraph.IN)))
                        / len(
                            list(
                                cl_dag.graph.bfsiter(
                                    cl_dag.get_vertex(_target_cl), mode=igraph.IN
                                )
                            )
                        )
                        for intermediate in intermediates
                        if ref_cl_set.intersection(
                            set(cl_dag.graph.bfsiter(intermediate, mode=igraph.IN))
                        )
                    ]
                )
            else:
                cache[_target_cl] = 0
            cl_accuracy[i] = cache[_target_cl]
        accuracy_dict[query_cl] = [cl_accuracy.size, cl_accuracy.mean(), True]

    # specificity
    for query_cl in negative_cl:
        target_cl = target[source == query_cl]
        cl_accuracy = np.in1d(target_cl, ["rejected", "unassigned"])
        accuracy_dict[query_cl] = [cl_accuracy.size, cl_accuracy.mean(), False]

    return pd.DataFrame(accuracy_dict, index=("cell number", "accuracy", "positive")).T

def benchmark_processedSVs_against_knownSVs_inHouse(svtype_to_predsvfile, know_SV_dict, fileprefix, replace=False, add_integrated_benchmarking=True, consider_all_svtypes=False, tol_bp=50, fast_mode=False, pct_overlap=0.75):

    """Takes two dictionaries that map some SVfiles. It runs, for all the types in svtype_to_predsvfile, a benchmarking against the known ones, writing a file under fileprefix. It returns a df of this benchmark, created with functions written here. It returns as matching events those that have an overlap of at least 50 bp.

    know_SV_dict marks the expected events. If they do not exist you have 0 accuracy.

    add_integrated_benchmarking indicates whether to perform a global benchmarking (not only per svtype).

    The 'analysis_benchmarking' feature was removed from this version 

    fast_mode indicates to use bedmap for the comparisons.

    consider_all_svtypes defines if all the SVtypes should be considered. If False, it will only consider the svtypes from the known dict
    """

    # map cmplex events to a boolean field
    complexEvt_to_boolField = {"translocations":"Balanced", "insertions":"Copied"}


    # initialize benchmark dict
    benchmark_dict = {}

    # define the svtypes to consider
    if consider_all_svtypes is True: all_svtypes_benchmarking = set(svtype_to_fieldsDict)
    else: all_svtypes_benchmarking = set(know_SV_dict)

    # go through each type of event
    for svtype in all_svtypes_benchmarking:
        #print_if_verbose("benchmarking %s"%svtype)

        # load predicted df
        if svtype in svtype_to_predsvfile.keys():

            if type(svtype_to_predsvfile[svtype])==str: df_predicted = pd.read_csv(svtype_to_predsvfile[svtype], sep="\t")
            else: df_predicted = svtype_to_predsvfile[svtype]

        else: df_predicted = pd.DataFrame()

        # load known df
        if svtype in know_SV_dict.keys():

            if type(know_SV_dict[svtype])==str: df_known = pd.read_csv(know_SV_dict[svtype], sep="\t")
            else: df_known = know_SV_dict[svtype]

        else: df_known = pd.DataFrame(columns=svtype_to_fieldsDict[svtype]["all_fields"])

        # define the fields to find overlaps
        equal_fields = svtype_to_fieldsDict[svtype]["equal_fields"]
        approximate_fields = svtype_to_fieldsDict[svtype]["approximate_fields"]
        chromField_to_posFields = svtype_to_fieldsDict[svtype]["chromField_to_posFields"]

        # get the dict of the benchmark
        if fast_mode is False: dict_benchmark_svtype = get_SVbenchmark_dict(df_predicted, df_known, equal_fields=equal_fields, approximate_fields=approximate_fields, chromField_to_posFields=chromField_to_posFields, tol_bp=tol_bp, pct_overlap=pct_overlap)

        else: 

            if fileprefix is None: raise ValueError("The function get_SVbenchmark_dict_fast needs a fileprefix in fast_mode=True")
            tmpdir = "%s_get_SVbenchmark_dict_fast_tmpdir"%fileprefix
            dict_benchmark_svtype = get_SVbenchmark_dict_fast(df_predicted, df_known, tmpdir, equal_fields=equal_fields, approximate_fields=approximate_fields, chromField_to_posFields=chromField_to_posFields, tol_bp=tol_bp, pct_overlap=pct_overlap)

        dict_benchmark_svtype["svtype"] = svtype

        # keep
        benchmark_dict[svtype] = dict_benchmark_svtype

    # get the benchmarking
    df_benchmark = pd.DataFrame(benchmark_dict).transpose()

    ###### perform integrated benchmarking #####
    if add_integrated_benchmarking is True:

        # get a per-filt row
        integrated_df_benchmark = pd.DataFrame({"integrated": get_integrated_benchmarking_fields_series_for_setFilters_df(df_benchmark)}).transpose()

        # keep
        df_benchmark = df_benchmark.append(integrated_df_benchmark[list(df_benchmark.keys())])

    ###########################################

    return df_benchmark

