def forward(self, x: torch.Tensor) -> typing.Tuple[torch.Tensor]:
    x = self.mlp(x)
    gau = self.gau(x)
    cat = self.softmax(self.cat(x))
    latent = gau + self.mat(cat)
    return latent, (gau, cat)

