def print_header(vcf_obj, include, exclude, samples=None):
    """Print the header of a vcf obj

    Parameters
    ----------
    vcf_obj: cyvcf2.VCF
    include: tuple
        set of strings with info fields that should be included
    exclude: tuple
        set of strings with info fields that should be excluded
    samples: list
            list of samples to extract.
    """
    if not samples is None:
        vcf_obj.set_samples(samples)

    if include:
        include_list = ['ID='+inc+','for inc in include]
    if exclude:
        exclude_list = ['ID='+exc+','for exc in exclude]

    for header_line in vcf_obj.raw_header.split('\n'):
        if len(header_line) == 0:
            continue
        print_line = True
        if 'INFO' not in header_line:
            pass
        elif include:
            print_line = sum(map(header_line.count, include_list))
        elif exclude:
            print_line = not sum(map(header_line.count, exclude_list))
        if print_line:
            click.echo(header_line)

def get_population_AF(self, svcall: SVCall) -> tuple[float, int] | None:
    """
    Returns the population AF and population size for the given SVCall. Returns None if the variant is not found in the population SNF.
    """
    if svcall.contig not in self._blocks:
        self._blocks[svcall.contig] = self.get_all_blocks(svcall.contig)

    block = str(self._calculate_block_index(svcall.pos))
    best_dist = None
    best_variant = None
    try:
        for pv in self._blocks[svcall.contig][block][svcall.svtype]:
            pv: PopulationVariant
            dist = pv.match(svcall)
            if dist is not None:
                if best_dist is None or dist < best_dist:
                    best_dist = dist
                    best_variant = pv
    except KeyError:
        ...
    else:
        if best_variant is not None:
            return round(best_variant.af, 5), best_variant.genotyped_sample_count

    return None

