def vel_s(
    self, U: Union[csr_matrix, np.ndarray], S: Union[csr_matrix, np.ndarray]
) -> Union[csr_matrix, np.ndarray]:
    """Calculate the unspliced mRNA velocity.

    Args:
        U: A matrix of unspliced mRNA counts. Dimension: genes x cells.
        S: A matrix of spliced mRNA counts. Dimension: genes x cells.

    Returns:
        Each column of V is a velocity vector for the corresponding cell. Dimension: genes x cells.
    """

    t = self.parameters["t"]
    t_uniq, t_uniq_cnt = np.unique(self.parameters["t"], return_counts=True)
    if self.parameters["gamma"] is not None:
        if self.parameters["beta"] is None and self.parameters["alpha"] is not None:
            no_beta = True
            self.parameters["beta"] = self.parameters["alpha"]
        else:
            no_beta = False

        if self.parameters["beta"].ndim == 1:
            beta = np.repeat(self.parameters["beta"].reshape((-1, 1)), U.shape[1], axis=1)
        elif self.parameters["beta"].shape[1] == U.shape[1]:
            beta = self.parameters["beta"]
        elif self.parameters["beta"].shape[1] == len(t_uniq) and len(t_uniq) > 1:
            beta = np.zeros_like(U.shape)
            for i in range(len(t_uniq)):
                cell_inds = t == t_uniq[i]
                beta[:, cell_inds] = np.repeat(self.parameters["beta"][:, i], t_uniq_cnt[i], axis=1)
        else:
            beta = np.repeat(self.parameters["beta"], U.shape[1], axis=1)

        if len(self.parameters["gamma"].shape) == 1:
            gamma = np.repeat(
                self.parameters["gamma"].reshape((-1, 1)),
                U.shape[1],
                axis=1,
            )
        elif self.parameters["gamma"].shape[1] == U.shape[1]:
            gamma = self.parameters["gamma"]
        elif self.parameters["gamma"].shape[1] == len(t_uniq) and len(t_uniq) > 1:
            gamma = np.zeros_like(U.shape)
            for i in range(len(t_uniq)):
                cell_inds = t == t_uniq[i]
                gamma[:, cell_inds] = np.repeat(self.parameters["gamma"][:, i], t_uniq_cnt[i], axis=1)
        else:
            gamma = np.repeat(self.parameters["gamma"], U.shape[1], axis=1)

        if no_beta:
            V = (
                csr_matrix(beta, dtype=np.float64) - csr_matrix(gamma, dtype=np.float64).multiply(S)
                if issparse(U)
                else beta - gamma * S
            )
        else:
            V = (
                csr_matrix(beta, dtype=np.float64).multiply(U) - csr_matrix(gamma, dtype=np.float64).multiply(S)
                if issparse(U)
                else beta * U - gamma * S
            )
    else:
        V = np.nan
    return V

def mrna_sequence(self):
    """
    a list of genomic sequences for the mRNA's
    """
    return self._cds_sequence(self.coding_exons)

def __call__(self, loss):
    if not hasattr(self, 'layer'):
        raise Exception('Need to call `set_layer` on '
                        'ActivityRegularizer instance '
                        'before calling the instance.')
    regularized_loss = loss
    for i in range(len(self.layer.inbound_nodes)):
        output = K.sigmoid(0.1 * self.layer.get_output_at(i))
        #output = self.layer.get_output_at(i)
        p_hat = K.mean(K.abs(output))
        regularized_loss += self.l * kl_divergence(self.p, p_hat)
    return K.in_train_phase(regularized_loss, loss)

def store_calls(self, svcalls: list[SVCall]) -> None:
    super().store_calls(svcalls)

    if self.svcalls is None:
        self.svcalls = []
    self.svcalls.extend(svcalls)

def deviation_loss(self) -> torch.Tensor:
    return self.deviation_reg * (
        self.mlp.deviation_loss()
        + self.mu.deviation_loss()
        + self.log_theta.deviation_loss()
        + self.pi.deviation_loss()
    )

def reset_adata_X(adata: AnnData, experiment_type: str, has_labeling: bool, has_splicing: bool):
    if has_labeling:
        if experiment_type.lower() in [
            "one-shot",
            "kin",
            "mixture",
            "mix_std_stm",
            "kinetics",
            "mix_pulse_chase",
            "mix_kin_deg",
        ]:
            adata.X = adata.layers["total"].copy()
        if experiment_type.lower() in ["deg", "degradation"] and has_splicing:
            adata.X = adata.layers["spliced"].copy()
        if experiment_type.lower() in ["deg", "degradation"] and not has_splicing:
            main_warning(
                "It is not possible to calculate RNA velocity from a degradation experiment which has no "
                "splicing information."
            )
            adata.X = adata.layers["total"].copy()
        else:
            adata.X = adata.layers["total"].copy()
    else:
        adata.X = adata.layers["spliced"].copy()

def assemble(args, run_params, out_file, log_file, config_path):
    logger.info("Assembling disjointigs")
    logger.debug("-----Begin assembly log------")
    cmdline = [ASSEMBLE_BIN, "assemble", "--reads", ",".join(args.reads), "--out-asm", out_file,
               "--config", config_path, "--log", log_file, "--threads", str(1 if args.deterministic else args.threads)]
    if args.debug:
        cmdline.append("--debug")
    if args.meta:
        cmdline.append("--meta")
    #if args.short_mode:
    #    cmdline.append("--short")
    if args.genome_size:
        cmdline.extend(["--genome-size", str(args.genome_size)])
    #if args.kmer_size:
    #    cmdline.extend(["--kmer", str(args.kmer_size)])

    cmdline.extend(["--min-ovlp", str(run_params["min_overlap"])])
    if run_params["min_read_length"] > 0:
        cmdline.extend(["--min-read", str(run_params["min_read_length"])])

    if args.extra_params:
        cmdline.extend(["--extra-params", args.extra_params])

    #if args.min_kmer_count is not None:
    #    cmdline.extend(["-m", str(args.min_kmer_count)])
    #if args.max_kmer_count is not None:
    #    cmdline.extend(["-x", str(args.max_kmer_count)])

    try:
        logger.debug("Running: " + " ".join(cmdline))
        subprocess.check_call(cmdline)
    except subprocess.CalledProcessError as e:
        if e.returncode == -9:
            logger.error("Looks like the system ran out of memory")
        raise AssembleException(str(e))
    except OSError as e:
        raise AssembleException(str(e))

