def get_graph_tool_from_adjacency(adjacency, directed=False, use_weights=False):
    """Get graph-tool graph from adjacency matrix."""

    adj = adjacency
    weights = None

    if isinstance(adjacency, ssp.csr_matrix):
        if not directed:
            adj = ssp.triu(adjacency, 1)
        idx = adj.nonzero()
        if use_weights:
            weights = adj.data

    else:
        if not directed:
            adj = np.triu(adjacency, 1)
        idx = np.nonzero(adj)
        if use_weights:
            weights = adj[idx]    

    if use_weights:
        g = gt.Graph(np.array([idx[0], idx[1], weights]).T, 
                     eprops=[("weight", "double")],
                     directed=directed)
    else:
        g = gt.Graph(np.transpose(idx), directed=directed)

    if g.num_vertices() != adjacency.shape[0]:
        logg.warning(
            f'The constructed graph has only {g.num_vertices()} nodes. '
            'Your adjacency matrix contained redundant nodes.'
        )
    return g

def get_config(self):
    config = {'beta_init': self.beta_init,
              'activity_regularizer': self.activity_regularizer.get_config()
                                      if self.activity_regularizer else None,}
    base_config = super(ParametricSigmoid, self).get_config()
    return dict(list(base_config.items()) + list(config.items()))

def write(self):
    if not self.path:
        return 'path not valid: {}'.format(self.path)

    if not self.transcripts:
        return 'no transcripts to write'

    transcripts_by_gene_id = _group_transcripts_by_gene_id(
        self.transcripts)
    with open(self.path, 'wt') as f_handle:
        for gene_id, transcripts in transcripts_by_gene_id.items():
            error = _write_lines_for_gene_id(f_handle, gene_id,
                                             transcripts)
            if error:
                return 'error in gene_id: {}: {}'.format(gene_id, error)

    return None

def deviation_loss(self) -> torch.Tensor:
    loss = torch.tensor(0)
    for _hidden in self.hiddens:
        loss = loss + _hidden.deviation_loss()
    return loss

def _get_min_query_size(self):
    try:
        size_b = self.reader.get("cluster", "min_query_size")
        size_v = int(size_b[:-1])
        size_unit = size_b[-1].upper()
        if size_unit not in ["M", "G"]:
            raise ValueError("Min query size unit must be M or G")
        min_size = size_v * 1024 * 1024
        if size_unit == "G":
            min_size *= 1024
        return min_size
    except (NoOptionError, NoSectionError):
        return 0

