def run_tune(train_step, epoch, steps_per_tune):
  """Runs evaluation on held out eval set."""
  logging.info(
      'Running tune at step=%d epoch=%d',
      train_step,
      epoch,
  )
  for tune_step in range(0, steps_per_tune, config.steps_per_iter):
    with tf.profiler.experimental.Trace('tune', step_num=tune_step, _r=1):
      if roundup(tune_step, config.steps_per_iter) > steps_per_tune:
        steps_per_iter = steps_per_tune % config.steps_per_iter
      else:
        steps_per_iter = config.steps_per_iter
      if (
          tune_step
          % roundup(config.log_every_steps, config.steps_per_iter)
          == 0
      ):
        logging.info(
            'Tune step %s / %s (%s%%)',
            tune_step,
            steps_per_tune,
            round(float(tune_step) / float(steps_per_tune), 1) * 100.0,
        )
      distributed_tune_step(
          tune_ds, tf.constant(steps_per_iter, dtype=tf.int64)
      )

  metric_writer.write_scalars(
      train_step,
      {f'tune/{x.name}': x.result() for x in state.tune_metrics},
  )

def PCA(Y, components):
	"""run PCA, retrieving the first (components) principle components
	return [s0, eig, w0]
	s0: factors
	w0: weights
	"""
	sv = LA.svd(Y, full_matrices=0);
	[s0, w0] = [sv[0][:, 0:components], SP.dot(SP.diag(sv[1]), sv[2]).T[:, 0:components]]
	v = s0.std(axis=0)
	s0 /= v;
	w0 *= v;
	return [s0, w0]

def deviation_loss(self) -> torch.Tensor:
    return self.deviation_reg * (
        self.mlp.deviation_loss() + self.gau.deviation_loss()
    )

def get_circular_component(self, circular_pseudotime):
    if self.n_circular_unit == 1:
        return numpy.hstack([numpy.sin(circular_pseudotime),
                             numpy.cos(circular_pseudotime)]) @ self.get_circular_loadings()
    else:
        temp = []
        for i in range(self.n_circular_unit):
            temp.append(numpy.sin(circular_pseudotime[:, [i]]))
            temp.append(numpy.cos(circular_pseudotime[:, [i]]))
        return numpy.hstack(temp) @ self.get_circular_loadings()

