def countPoly(self, read):
    polyArray = ["A", "T", "C", "G"]
    for p in polyArray:
        if p*self.__poly_x_num in read:
            count = self.__poly_x_num
            pos = read.find(p*self.__poly_x_num)
            for c in read[pos + self.__poly_x_num:]:
                if c == p:
                    count += 1
                else:
                    break
            return p, count
    return None, 0

