def filter(
    self,
    by: str = "pval",
    cutoff: float = 0.05,
    model_tolerance: int = 0,
    n_jobs: int = 1,
) -> "Hits":
    r"""
    Filter hits by posterior distance or p-value

    Parameters
    ----------
    by
        Specifies a metric based on which to filter hits.
        Should be among {"dist", "pval"}.
    cutoff
        Cutoff when filtering hits.
    model_tolerance
        Maximal number of models allowed in which the cutoff is not
        satisfied, above which the query cell will be rejected.
        Irrelevant for reconciled hits.
    n_jobs
        Number of parallel jobs to run.

    Returns
    -------
    filtered_hits
        Hit object containing remaining hits after filtering
    """
    if by == "pval":
        assert self.pval is not None
        by = Hits.FILTER_BY_PVAL
    else:  # by == "dist"
        by = Hits.FILTER_BY_DIST
    if self.dist[0].ndim == 1:
        hits, dist, pval = [
            _
            for _ in zip(
                *joblib.Parallel(n_jobs=n_jobs, backend="threading")(
                    joblib.delayed(self._filter_reconciled_hits)(
                        _hits, _dist, _pval, by, cutoff
                    )
                    for _hits, _dist, _pval in zip(self.hits, self.dist, self.pval)
                )
            )
        ]
    else:
        hits, dist, pval = [
            _
            for _ in zip(
                *joblib.Parallel(n_jobs=n_jobs, backend="threading")(
                    joblib.delayed(self._filter_hits)(
                        _hits, _dist, _pval, by, cutoff, model_tolerance
                    )
                    for _hits, _dist, _pval in zip(self.hits, self.dist, self.pval)
                )
            )
        ]
    return Hits(self.blast, hits, dist, pval, self.query)

def _compute_profile(alignment, ref_sequence):
    """
    Computes alignment profile
    """
    if len(alignment) == 0:
        raise Exception("No alignmemnts!")
    genome_len = alignment[0].trg_len

    #max_aln_err = cfg.vals["err_modes"][platform]["max_aln_error"]
    min_aln_len = min(cfg.vals["min_polish_aln_len"], genome_len // 2)
    aln_errors = []
    #filtered = 0
    profile = [ProfileInfo() for _ in range(genome_len)]

    for i in range(genome_len):
        profile[i].nucl = ref_sequence[i]

    for aln in alignment:
        #if aln.err_rate > max_aln_err or len(aln.qry_seq) < min_aln_len:
        if len(aln.qry_seq) < min_aln_len:
            #filtered += 1
            continue

        aln_errors.append(aln.err_rate)

        qry_seq = shift_gaps(aln.trg_seq, aln.qry_seq)
        trg_seq = shift_gaps(qry_seq, aln.trg_seq)

        trg_pos = aln.trg_start
        for trg_nuc, qry_nuc in zip(trg_seq, qry_seq):
            if trg_nuc == "-":
                trg_pos -= 1
            #if trg_pos >= genome_len:
            #    trg_pos -= genome_len

            prof_elem = profile[trg_pos]
            if trg_nuc == "-":
                prof_elem.insertions[aln.qry_id] += qry_nuc
                #prof_elem.num_inserts += 1
            else:
                #prof_elem.nucl = trg_nuc
                prof_elem.coverage += 1

                if qry_nuc == "-":
                    prof_elem.num_deletions += 1
                elif trg_nuc != qry_nuc:
                    prof_elem.num_missmatch += 1

            trg_pos += 1

    for i in range(genome_len):
        for ins_read, ins_str in profile[i].insertions.items():
            profile[i].propagated_ins += 1
            span = len(ins_str)
            for j in range(max(0, i - span), i):
                profile[j].propagated_ins += 1
            for j in range(i + 1, min(i + span + 1, genome_len)):
                profile[j].propagated_ins += 1


    #logger.debug("Filtered: {0} out of {1}".format(filtered, len(alignment)))
    return profile, aln_errors

def preprocess(
    x: torch.Tensor, libs: torch.Tensor, noisy: bool = True
) -> torch.Tensor:
    x = x / (libs / 10000)
    if noisy:
        x = D.Poisson(rate=x).sample()
    x = x.log1p()
    return x

def flatten_list(my_list):
    flat = []
    for entry in my_list:
        if type(entry) == list:
            flat.extend(flatten_list(entry))
        else:
            flat.append(entry)

    return flat

def objective(self):
    """Compute divergence of target matrix from its NMF estimate."""
    Va = dot(dot(self.W, self.S), self.H)
    return (multiply(self.V, sop(elop(self.V, Va, div), op=np.log)) - self.V + Va).sum()

def objective(self):
    """Compute squared Frobenius norm of a target matrix and its NMF estimate."""
    R = self.V - dot(self.W, self.H)
    return power(R, 2).sum()

