def analyse_repeats(args, run_params, input_assembly, out_folder,
                    log_file, config_file):
    logger.debug("-----Begin repeat analyser log------")

    cmdline = [REPEAT_BIN, "repeat", "--disjointigs", input_assembly,
               "--reads", ",".join(args.reads), "--out-dir", out_folder,
               "--config", config_file, "--log", log_file,
               "--threads", str(args.threads)]
    if args.debug:
        cmdline.append("--debug")
    if args.meta:
        cmdline.append("--meta")
    if args.keep_haplotypes:
        cmdline.append("--keep-haplotypes")
    #if args.kmer_size:
    #    cmdline.extend(["--kmer", str(args.kmer_size)])
    cmdline.extend(["--min-ovlp", str(run_params["min_overlap"])])

    if args.extra_params:
        cmdline.extend(["--extra-params", args.extra_params])

    try:
        logger.debug("Running: " + " ".join(cmdline))
        subprocess.check_call(cmdline)
    except subprocess.CalledProcessError as e:
        if e.returncode == -9:
            logger.error("Looks like the system ran out of memory")
        raise RepeatException(str(e))
    except OSError as e:
        raise RepeatException(str(e))

def nucleosome_signal(adata,
                      fragments,
                      n=10000):
    """
    Calculates the nucleosome signal (mononucleosomal to nucleosome-free ratio).

    Args:
        adata: AnnData
        fragments: path to fragments file
        n: number of cell-associated fragments to consider per barcode in AnnData

    Returns:
        None
    """

    n = adata.n_obs * n

    valid_bcs = set(adata.obs.index)

    comment = "#"
    check_for_comments = True
    use_strip = None

    fragment_info = {bc: [0, 0, []] for bc in valid_bcs}

    if fragments.endswith(".gz"):
        fh = gzip.open(fragments, mode="rt")
    else:
        fh = open(fragments, mode="r")

    c = 0

    for line in fh:

        if check_for_comments:
            if line.startswith(comment):
                continue
            else:
                check_for_comments = False

        if use_strip is None:
            line_split = line.strip().split("\t")
            if len(line_split) == 4:
                use_strip = True
            else:
                use_strip = False
        elif not use_strip:
            line_split = line.split("\t")
        else:
            line_split = line.strip().split("\t")

        bc = line_split[3]
        if bc not in valid_bcs:
            continue

        chrom = line_split[0]
        start = int(line_split[1])
        stop = int(line_split[2])

        length = stop - start
        if length < 147:
            fragment_info[bc][0] += 1
        elif length >= 147 and length < 294:
            fragment_info[bc][1] += 1

        fragment_info[bc][2].append(length)

        c += 1
        if c == n:
            break

    nucleosome_signal = dict()

    for bc, (nuc_free, mono_nuc, lns) in fragment_info.items():
        tmp = (
            mono_nuc / nuc_free if nuc_free != 0 else np.nan,
            lns
        )
        nucleosome_signal[bc] = tmp

    adata.obs["nucleosome_signal"] = [nucleosome_signal[bc][0] for bc in adata.obs.index]
    adata.uns["fragment_lengths"] = {bc: nucleosome_signal[bc][1] for bc in adata.obs.index}

