            if fileprefix is None: raise ValueError("The function get_SVbenchmark_dict_fast needs a fileprefix in fast_mode=True")
            tmpdir = "%s_get_SVbenchmark_dict_fast_tmpdir"%fileprefix
            dict_benchmark_svtype = get_SVbenchmark_dict_fast(df_predicted, df_known, tmpdir, equal_fields=equal_fields, approximate_fields=approximate_fields, chromField_to_posFields=chromField_to_posFields, tol_bp=tol_bp, pct_overlap=pct_overlap)

        dict_benchmark_svtype["svtype"] = svtype

        # keep
        benchmark_dict[svtype] = dict_benchmark_svtype

    # get the benchmarking
    df_benchmark = pd.DataFrame(benchmark_dict).transpose()

    ###### perform integrated benchmarking #####
    if add_integrated_benchmarking is True:

        # get a per-filt row
        integrated_df_benchmark = pd.DataFrame({"integrated": get_integrated_benchmarking_fields_series_for_setFilters_df(df_benchmark)}).transpose()

        # keep
        df_benchmark = df_benchmark.append(integrated_df_benchmark[list(df_benchmark.keys())])

    ###########################################

    return df_benchmark

def gan_d_loss(
    y: torch.Tensor, y_hat: torch.Tensor, eps: float = 1e-8
) -> torch.Tensor:
    return -(torch.log(y_hat + eps) + torch.log(1 - y + eps)).mean()

