def _calc_read_counts(self, variant):
  tumor_i = self._get_tumor_index(variant, self._tumor_sample)
  ref_reads = int(variant.samples[tumor_i]['AD'][0])
  variant_reads = int(variant.samples[tumor_i]['AD'][1])
  total_reads = ref_reads + variant_reads

  return (ref_reads, total_reads)

def get_fractions_reads_for_ploidy(ploidy):

    """Takes a ploidy and returns the fraction_var and fraction_ref."""

    # define the fraction of reads that come from each genome
    if ploidy in {"haploid", "diploid_homo"}:

        fraction_var = 1.0
        fraction_ref = 0.0

    elif ploidy=="diploid_hetero":

        fraction_var = 0.5
        fraction_ref = 0.5 

    else:

        # These are specific combinations of genomes (polyploids or populations)
        try:
            typeGenome_to_ncopies = {x.split(":")[0] : int(x.split(":")[1]) for x in ploidy.split("_")}
            typeGenome_to_fraction_reads = {type_genome: ncopies / sum(typeGenome_to_ncopies.values()) for type_genome, ncopies in typeGenome_to_ncopies.items()}

        except: raise ValueError("ploidy %s is incorrect. The format is ref:2_var:1 , which would be one copy of variant genome for every two copies of reference genome"%ploidy)

        fraction_var = typeGenome_to_fraction_reads["var"]
        fraction_ref = typeGenome_to_fraction_reads["ref"]

    return fraction_var, fraction_ref

def get_allele_freq(r):

    if r["length_event"]>maxiumum_insert_size: return r["allele_frequency"]
    else: return r["allele_frequency_SmallEvent"]

def get_BLOSUM62_score_missense_variants(r):

    """adds the blosum62 score """

    # Blosum consequences
    if "missense_variant" in r.Consequence.split(","):

        # get aminoacids
        aa_ref, aa_alt = r.Amino_acids.split("/")
        if aa_ref==aa_alt: raise ValueError("aa can't be the same")

        # check aas
        matrix_dict = MatrixInfo.blosum62
        all_considered_aa = set.union(*[set(x) for x in matrix_dict.keys()])
        if aa_ref not in all_considered_aa: raise ValueError("unconsidered aa_ref: %s"%aa_ref)
        if aa_alt not in all_considered_aa: raise ValueError("unconsidered aa_alt: %s"%aa_alt)

        # define the substitution tuple
        possible_subs_tuples = {(aa_ref, aa_alt), (aa_alt, aa_ref)}.intersection(set(matrix_dict.keys()))
        if len(possible_subs_tuples)!=1: raise ValueError("there should be only one subs tuple in the matrix")
        subs_tuple = next(iter(possible_subs_tuples))

        # get the score
        return cp.deepcopy(int(matrix_dict[subs_tuple]))

    # no score
    else:
        return 0

