def resolve_block_groups(svtype, svcands, groups_initial, config):
    """For clustering groups of SVs for combining .snfs (multi-call)"""

    # TODO: Remove sorting
    groups = groups_initial
    for svcand in sorted(svcands, key=lambda cand: cand.support, reverse=True):
        best_group = None
        best_dist = math.inf

        if svtype == "BND":
            mate_contig, mate_ref_start = svcand.bnd_info.mate_contig, svcand.bnd_info.mate_ref_start
            for group in groups:
                # TODO: Favor bigger groups in placement
                dist = abs(group.pos_mean - svcand.pos) + abs(group.bnd_mate_ref_start_mean - mate_ref_start)
                if dist < best_dist and dist <= config.cluster_merge_bnd * 2 and group.bnd_mate_contig == mate_contig:
                    if not config.combine_separate_intra or svcand.sample_internal_id not in group.included_samples:
                        best_group = group
                        best_dist = dist
        else:
            for group in groups:
                # TODO: Favor bigger groups in placement
                dist = abs(group.pos_mean - svcand.pos) + abs(abs(group.len_mean) - abs(svcand.svlen))  # check if group.pos_mean is updated or stays the same for the first SV starting the group
                minlen = float(min(abs(group.len_mean), abs(svcand.svlen)))
                if minlen > 0 and dist < best_dist and dist <= config.combine_match * math.sqrt(minlen) and dist <= config.combine_match_max:
                    if (not config.combine_separate_intra or svcand.sample_internal_id not in group.included_samples) and group.align_call(svcand, config.combine_pctseq):
                        best_group = group
                        best_dist = dist

        if best_group is None:
            groups.append(
                sv.SVGroup.from_candidate(svcand)
            )
        else:
            best_group.add_candidate(svcand)
    return groups

def _processFile(FILENAME,useStdIn):
    if not useStdIn:
        header=""
        lines=[]
        for line in open(FILENAME,"r"):
            if line[0]=="#":
                header+=line.strip()+"\n"
            else:
                lines.append(line.strip().split())
    else:
        header=""
        lines=[]
        for line in sys.stdin:
            if line[0]=="#":
                header+=line.strip()+"\n"
            else:
                lines.append(line.strip().split())
    return header[:-1], [[x[0],int(x[1]),int(x[2]),x[3],int(x[4]),int(x[5]), x[6:]] for x in lines]

def call(self, config, task) -> Optional[SVCall]:
    """
    Call this group, returning either an SVCall or None.
    """
    first_cand = self.candidates[0]

    # Filtering
    samples_count = float(len(config.snf_input_info))
    n_samples = len(config.snf_input_info)
    sample_internal_ids = set(sample["internal_id"] for sample in config.snf_input_info)
    total_count = len(self.included_samples)
    pass_count = sum(cand.qc for cand in self.candidates)
    qc = ((pass_count > 0 and pass_count / samples_count >= config.combine_high_confidence) or
          (total_count / samples_count >= config.combine_low_confidence and
           total_count >= config.combine_low_confidence_abs))

    if not qc:
        if config.no_qc and n_samples == 1:
            pass
        else:
            return None

    if not config.combine_output_filtered and not any(cand.qc and cand.filter == "PASS" for cand in self.candidates):
        if config.no_qc and n_samples == 1:
            pass
        else:
            return None

    rnames = [] if config.output_rnames else None
    genotypes = {}

    for cand in self.candidates:
        if rnames is not None and cand.rnames is not None:
            rnames.extend(cand.rnames)

        if 0 not in cand.genotypes:
            cand.genotypes[0] = (".", ".", 0, 0, cand.support, (None, None))
        if cand.sample_internal_id in genotypes:
            # Intra-sample merging
            a, b, gt_qual, dr, dv, ps = cand.genotypes[0]
            curr_a, curr_b, curr_gt_qual, curr_dr, curr_dv, curr_ps, curr_id = genotypes[cand.sample_internal_id]
            new_id = curr_id + "," + config.id_prefix + cand.id
            if (curr_a == ".") or (a != "." and (a, b) >= (curr_a, curr_b)):
                genotypes[cand.sample_internal_id] = (a, b, gt_qual, dr, dv, ps, new_id)
            else:
                genotypes[cand.sample_internal_id] = (curr_a, curr_b, curr_gt_qual, curr_dr, curr_dv, curr_ps, new_id)
        else:
            a, b, gt_qual, dr, dv, ps = cand.genotypes[0]
            genotypes[cand.sample_internal_id] = (a, b, gt_qual, dr, dv, ps, config.id_prefix + cand.id)

    for sample_internal_id in sample_internal_ids:
        if sample_internal_id in genotypes:
            continue
        coverage = self.coverages_nonincluded[sample_internal_id]
        if coverage >= config.combine_null_min_coverage:
            genotypes[sample_internal_id] = (0, 0, 0, coverage, 0, (None, None), "NULL")
        else:
            genotypes[sample_internal_id] = (".", ".", 0, coverage, 0, (None, None), "NULL")

    if config.combine_consensus:
        genotypes_consensus = {}
        for a, b, gt_qual, dr, dv in genotypes.values():
            if not (a, b) in genotypes_consensus:
                genotypes_consensus[(a, b)] = {"count": 0, "qual": list(), "dr": list(), "dv": list()}
            genotypes_consensus[(a, b)]["count"] += 1
            genotypes_consensus[(a, b)]["qual"].append(gt_qual)
            genotypes_consensus[(a, b)]["dr"].append(dr)
            genotypes_consensus[(a, b)]["dv"].append(dv)
        most_common_count = genotypes_consensus[sorted(genotypes_consensus,
                                                       key=lambda k: genotypes_consensus[k]["count"],
                                                       reverse=True)[0]]["count"]
        most_common_gt = [gt for gt in genotypes_consensus if genotypes_consensus[gt]["count"] == most_common_count]
        cons_a, cons_b = max(most_common_gt)
        consensus_info = genotypes_consensus[(cons_a, cons_b)]
        genotypes = {0: (cons_a, cons_b, int(sum(consensus_info["qual"]) / consensus_info["count"]),
                         sum(consensus_info["dr"]), sum(consensus_info["dv"]))}
        if cons_a != 1 and cons_b != 1:
            if config.no_qc and n_samples == 1:
                pass
            else:
                return None

    if config.combine_pair_relabel:
        max_gt = (0, 0)
        for sample_id in genotypes:
            a, b, qual, dr, dv, ps, new_id = genotypes[sample_id]
            if qual > config.combine_pair_relabel_threshold and a != ".":
                max_gt = max(max_gt, (a, b))

        if max_gt != (0, 0):
            for sample_id in genotypes:
                a, b, qual, dr, dv, ps, new_id = genotypes[sample_id]
                if qual < config.combine_pair_relabel_threshold and a != ".":
                    max_a, max_b = max_gt
                    genotypes[sample_id] = (max_a, max_b, qual, dr, dv, ps, new_id)

    svcall_pos = int(util.median(cand.pos for cand in self.candidates))
    svcall_svlen = int(util.median(cand.svlen for cand in self.candidates))

    if config.dev_emit_sv_lengths:
        svcall_svlens: list[int] | None = [length in cand_lengths
                                           for cand_lengths in self.candidates
                                           for length in cand_lengths.svlens]
    else:
        svcall_svlens = None

    svcall_alt = first_cand.alt
    svcall_alt_mindist = abs(len(svcall_alt) - svcall_svlen)
    if first_cand.svtype == "INS":
        svcall_end = svcall_pos
        for cand in self.candidates:
            dist = abs(len(cand.alt) - svcall_svlen)
            if dist < svcall_alt_mindist:
                svcall_alt_mindist = dist
                svcall_alt = cand.alt
    else:
        svcall_end = svcall_pos + abs(svcall_svlen)

    svcall = SVCall(contig=first_cand.contig,
                    pos=svcall_pos if config.dev_combine_medians else first_cand.pos,
                    id=f"{first_cand.svtype}.{task.sv_id:X}M{task.id:X}",
                    ref="N",
                    alt=svcall_alt,
                    qual=util.mean_or_none_round(int(cand.qual) for cand in self.candidates if cand.qual is not None),
                    filter="PASS" if n_samples != 1 else first_cand.filter,
                    info=dict() if n_samples != 1 else first_cand.info,
                    svtype=first_cand.svtype,
                    svlen=svcall_svlen if config.dev_combine_medians else first_cand.svlen,
                    svlens=svcall_svlens,
                    end=svcall_end if config.dev_combine_medians else first_cand.end,
                    genotypes=genotypes,
                    precise=sum(int(cand.precise) for cand in self.candidates) / float(len(self.candidates)) > 0.5,
                    support=round(util.mean(cand.support for cand in self.candidates)),
                    rnames=rnames,
                    postprocess=None,
                    qc=True,
                    nm=-1,
                    fwd=sum(cand.fwd for cand in self.candidates),
                    rev=sum(cand.rev for cand in self.candidates),
                    coverage_upstream=util.mean_or_none_round(cand.coverage_upstream for cand in self.candidates if cand.coverage_upstream is not None),
                    coverage_start=util.mean_or_none_round(cand.coverage_start for cand in self.candidates if cand.coverage_start is not None),
                    coverage_center=util.mean_or_none_round(cand.coverage_center for cand in self.candidates if cand.coverage_center is not None),
                    coverage_end=util.mean_or_none_round(cand.coverage_end for cand in self.candidates if cand.coverage_end is not None),
                    coverage_downstream=util.mean_or_none_round(cand.coverage_downstream for cand in self.candidates if cand.coverage_downstream is not None))

    if n_samples != 1:
        svcall.set_info("STDEV_POS", util.stdev(cand.pos for cand in self.candidates))
        svcall.set_info("STDEV_LEN", util.stdev(cand.svlen for cand in self.candidates))

    if abs(svcall.svlen) < config.minsvlen_screen:
        return None

    task.sv_id += 1

    if psnf := config.combine_population:
        pop_af = psnf.get_population_AF(svcall)
        af, sz = pop_af if pop_af is not None else (0, 0)
        svcall.set_info("POPULATION_AF", af)
        svcall.set_info("POPULATION_SIZE", sz)

    return svcall

def execute(self, worker: 'SnifflesWorker' = None):
    samples_headers_snf = {}
    for snf_info in self.config.snf_input_info:
        snf_in = snf.SNFile(self.config, open(snf_info["filename"], "rb"), filename=snf_info["filename"])
        snf_in.read_header()
        samples_headers_snf[snf_info["internal_id"]] = snf_in

        if self.config.combine_close_handles:
            snf_in.close()

    if self.config.combine_population:
        self.config.combine_population = PopulationSNF.open(self.config.combine_population)

    result = self.result_class(self, [], 0)

    # block_groups_keep_threshold=5000
    # TODO: Parameterize
    bin_min_size = self.config.combine_min_size
    bin_max_candidates = max(25, int(len(self.config.snf_input_info) * 0.5))
    overlap_abs = self.config.combine_overlap_abs
    support_threshold = self.config.combine_support_threshold

    sample_internal_ids = set(samples_headers_snf.keys())

    #
    # Load candidate SVs from all samples for each block separately and cluster them based on start position
    #
    candidates_processed = 0
    groups_keep = {svtype: list() for svtype in sv.TYPES}
    calls = []

    for cur, block_index in enumerate(self.block_indices):  # iterate over all blocks
        self.logger.info(f'Processing block {cur + 1}/{len(self.block_indices)} (active calls: {sv.SVCall._counter} groups: {sv.SVGroup._counter})')
        samples_blocks = {}
        if calls:
            result.store_calls(calls)
            calls = []

        for sample_internal_id, sample_snf in samples_headers_snf.items():
            blocks = sample_snf.read_blocks(self.contig, block_index)
            samples_blocks[sample_internal_id] = blocks
            # sample_internal_id is the number of the processed file
            # blocks is a list[dict[str, list[SVCall]]] {'INS': [...], 'DEL': [...], ...}

        for svtype in sv.TYPES:
            bins = {}
            for sample_internal_id, sample_snf in samples_headers_snf.items():  # fetch current block for each file
                blocks = samples_blocks[sample_internal_id]
                reqc = sample_snf.reqc

                if blocks is None:
                    continue
                for block in blocks:  # usually only 1 block
                    for cand in block[svtype]:
                        # if config.combine_pass_only and (cand.qc==False or cand.filter!="PASS"):
                        #    continue
                        if cand.support < support_threshold:
                            continue

                        if reqc:
                            postprocessing.genotype_sv(cand, self.config)

                        cand.sample_internal_id = sample_internal_id

                        bin = int(cand.pos / bin_min_size) * bin_min_size
                        if bin not in bins:
                            bins[bin] = [cand]
                        else:
                            bins[bin].append(cand)
                    candidates_processed += len(block[svtype])

            if len(bins) == 0:
                continue

            size = 0
            svcands = []
            keep = groups_keep[svtype]
            sorted_bins = sorted(bins)
            last_bin = sorted_bins[-1]
            for curr_bin in sorted_bins:
                svcands.extend(bins[curr_bin])  # here SVCalls from bins are collected...
                size += bin_min_size

                if (not self.config.combine_exhaustive and len(svcands) >= bin_max_candidates) or curr_bin == last_bin:
                    if len(svcands) == 0:
                        size = 0
                        continue

                    svgroups = cluster.resolve_block_groups(svtype, svcands, keep, self.config)
                    groups_call = []
                    keep = []
                    for group in svgroups:
                        coverage_bin = int(
                            group.pos_mean / self.config.coverage_binsize_combine) * self.config.coverage_binsize_combine
                        # High Intensity loop
                        for non_included_sample in sample_internal_ids - group.included_samples:
                            if samples_blocks[non_included_sample] is not None and coverage_bin in samples_blocks[non_included_sample][0]["_COVERAGE"]:
                                coverage = samples_blocks[non_included_sample][0]["_COVERAGE"][coverage_bin]
                            else:
                                coverage = 0
                            if non_included_sample in group.coverages_nonincluded:
                                group.coverages_nonincluded[non_included_sample] = max(
                                    coverage,
                                    group.coverages_nonincluded[non_included_sample]
                                )
                            else:
                                group.coverages_nonincluded[non_included_sample] = coverage

                        if abs(group.pos_mean - curr_bin) < max(size * 0.5, overlap_abs):
                            keep.append(group)
                        else:
                            groups_call.append(group)

                    calls.extend(sv.call_groups(groups_call, self.config, self))

                    size = 0
                    svcands = []

            groups_keep[svtype] = keep

    for svtype in groups_keep:
        calls.extend(sv.call_groups(groups_keep[svtype], self.config, self))

    if calls:
        result.store_calls(calls)

    result.finalize()
    return result

def _calculate_contig_coverages(self, *args, **kwargs) -> dict:
    """
    Coverages are not used in population SNFs.
    """
    return {}

def deviation_loss(self) -> torch.Tensor:
    return self.deviation_reg * (
        self.mlp.deviation_loss()
        + self.mu.deviation_loss()
        + self.log_theta.deviation_loss()
        + self.pi.deviation_loss()
    )

def get_population_AF(self, svcall: SVCall) -> tuple[float, int] | None:
    """
    Returns the population AF and population size for the given SVCall. Returns None if the variant is not found in the population SNF.
    """
    if svcall.contig not in self._blocks:
        self._blocks[svcall.contig] = self.get_all_blocks(svcall.contig)

    block = str(self._calculate_block_index(svcall.pos))
    best_dist = None
    best_variant = None
    try:
        for pv in self._blocks[svcall.contig][block][svcall.svtype]:
            pv: PopulationVariant
            dist = pv.match(svcall)
            if dist is not None:
                if best_dist is None or dist < best_dist:
                    best_dist = dist
                    best_variant = pv
    except KeyError:
        ...
    else:
        if best_variant is not None:
            return round(best_variant.af, 5), best_variant.genotyped_sample_count

    return None

def min_key(self, *k):
    """
    Returns the smallest key greater than or equal to the specified
    prefix.
    """
    if len(k) == 0:
        key = k
    else:
        key = self.key_to_ll(k)
    v = self.get_ll_object().get_min(key)
    return self.ll_to_key(v)

def resolve_block_groups(svtype, svcands, groups_initial, config):
    """For clustering groups of SVs for combining .snfs (multi-call)"""

    # TODO: Remove sorting
    groups = groups_initial
    for svcand in sorted(svcands, key=lambda cand: cand.support, reverse=True):
        best_group = None
        best_dist = math.inf

        if svtype == "BND":
            mate_contig, mate_ref_start = svcand.bnd_info.mate_contig, svcand.bnd_info.mate_ref_start
            for group in groups:
                # TODO: Favor bigger groups in placement
                dist = abs(group.pos_mean - svcand.pos) + abs(group.bnd_mate_ref_start_mean - mate_ref_start)
                if dist < best_dist and dist <= config.cluster_merge_bnd * 2 and group.bnd_mate_contig == mate_contig:
                    if not config.combine_separate_intra or svcand.sample_internal_id not in group.included_samples:
                        best_group = group
                        best_dist = dist
        else:
            for group in groups:
                # TODO: Favor bigger groups in placement
                dist = abs(group.pos_mean - svcand.pos) + abs(abs(group.len_mean) - abs(svcand.svlen))  # check if group.pos_mean is updated or stays the same for the first SV starting the group
                minlen = float(min(abs(group.len_mean), abs(svcand.svlen)))
                if minlen > 0 and dist < best_dist and dist <= config.combine_match * math.sqrt(minlen) and dist <= config.combine_match_max:
                    if (not config.combine_separate_intra or svcand.sample_internal_id not in group.included_samples) and group.align_call(svcand, config.combine_pctseq):
                        best_group = group
                        best_dist = dist

        if best_group is None:
            groups.append(
                sv.SVGroup.from_candidate(svcand)
            )
        else:
            best_group.add_candidate(svcand)
    return groups

def _calculate_support(self):
    """
    Rescale support for long insertions. This skews our support way higher than the number of reads we have!
    """
    return rescale_support(self.svcall, self.config)

def _calculate_af(self, support: int, coverage: int) -> float:
    """
    Calculate allele fraction
    """
    return support / float(coverage)

