def processStdinBed():
    import sys

    bed = {}
    header = ""
    for line in sys.stdin:
        if line == "\n":
            continue
        if line[0] == "#":
            header += line.strip() + "\n"
        else:
            line = line.strip().split()
            if line[0] in bed:
                bed[line[0]].append([int(line[1]), int(line[2]), line[3:]])
            else:
                bed[line[0]] = [[int(line[1]), int(line[2]), line[3:]]]
    return header[:-1], bed

