                             qual=int(QUAL) if QUAL != '.' else None,
                             filter=FILTER,
                             info=info_dict,
                             svtype=None,
                             svlen=None,
                             end=None,
                             rnames=None,
                             qc=True,
                             postprocess=None,
                             genotypes=None,
                             precise=None,
                             support=0,
                             fwd=0,
                             rev=0,
                             nm=-1)
            if len(call.alt) > len(call.ref):
                call.svtype = "INS"
                call.svlen = len(call.alt)
                call.end = call.pos
            else:
                call.svtype = "DEL"
                call.svlen = -len(call.ref)
                call.end = call.pos + call.svlen

            if "SVTYPE" in info_dict:
                call.svtype = info_dict["SVTYPE"]
                if call.svtype == "TRA":
                    call.svtype = "BND"

            if "SVLEN" in info_dict:
                call.svlen = int(info_dict["SVLEN"])
            if "SVLENGTHS`" in info_dict:
                call.svlens = info_dict["SVLENGTHS"]

            if "END" in info_dict:
                call.end = int(info_dict["END"])

            if call.svtype == "BND":
                bnd_parts = call.alt.replace("]", "[").split("[")
                if len(bnd_parts) > 2:
                    mate_contig, mate_ref_start = bnd_parts[1].split(":")
                    call.bnd_info = sv.SVCallBNDInfo(mate_contig=mate_contig, mate_ref_start=int(mate_ref_start),
                                                     is_first=(call.alt[0] == "N"), is_reverse=("]" in call.alt))
                else:
                    raise ValueError("BND ALT not formatted according to VCF 4.2 specifications")

            call.raw_vcf_line = line_strip
            call.raw_vcf_line_index = line_index
            yield call
        except Exception as e:
            util.fatal_error(f"Error parsing input VCF: Line {line_index}: {e}")

def build_leadtab(self):
    assert (self.lead_provider is None)

    config = self.config

    if config.input_is_cram and config.reference is not None:
        self.bam = pysam.AlignmentFile(config.input, config.input_mode, require_index=True, reference_filename=config.reference)
    else:
        self.bam = pysam.AlignmentFile(config.input, config.input_mode, require_index=True)
    self.lead_provider = leadprov.LeadProvider(config, self.id * config.task_read_id_offset_mult)
    externals = self.lead_provider.build_leadtab(self.regions if self.regions else [Region(self.contig, self.start, self.end)], self.bam)
    return externals, self.lead_provider.read_count

def reset_adata_X(adata: AnnData, experiment_type: str, has_labeling: bool, has_splicing: bool):
    if has_labeling:
        if experiment_type.lower() in [
            "one-shot",
            "kin",
            "mixture",
            "mix_std_stm",
            "kinetics",
            "mix_pulse_chase",
            "mix_kin_deg",
        ]:
            adata.X = adata.layers["total"].copy()
        if experiment_type.lower() in ["deg", "degradation"] and has_splicing:
            adata.X = adata.layers["spliced"].copy()
        if experiment_type.lower() in ["deg", "degradation"] and not has_splicing:
            main_warning(
                "It is not possible to calculate RNA velocity from a degradation experiment which has no "
                "splicing information."
            )
            adata.X = adata.layers["total"].copy()
        else:
            adata.X = adata.layers["total"].copy()
    else:
        adata.X = adata.layers["spliced"].copy()

def iter_kmers(seq, klen, skip):
    for i in range(0, len(seq) - klen, skip):
        yield (i, seq[i:i + klen])

